'use strict';
(globalThis.ABBATE_QUESTION_TRANSLATIONS||(globalThis.ABBATE_QUESTION_TRANSLATIONS={}))["lv"]={"g-flurpruefung":["Kas ir iekļauts vizuālajā un funkcionālajā pārbaudē pirms darba uzsākšanas?","Pirms dienas pirmās misijas.","Pārbaudiet tikai degvielas līmeni un transportlīdzekļa krāsu.","Pārbaudiet bremzes, stūri, dakšas, riepas un drošības ierīces saskaņā ar lietošanas instrukciju.","Veiciet testa braucienu ar paceltu kravu.","Ikdienas pārbaude ietver ar drošību saistītās daļas un funkcijas saskaņā ar lietošanas instrukciju."],"g-rueckhalt":["Kā tiekat galā ar esošo vadītāja ierobežotājsistēmas sistēmu?","Autoiekrāvējam ir obligāta ierobežotājsistēma.","Izmantojiet to pareizi braukšanas laikā.","Izmantojiet tikai uz nelīdzenām grīdām.","Īsiem braucieniem deaktivizējiet to.","Paredzētās ierobežotājsistēmas jāizmanto saskaņā ar ražotāja norādījumiem; tie nodrošina īpašu aizsardzību apgāšanās gadījumā."],"g-mangelmelden":["Kas attiecas uz iekrāvēju ar bojātu dakšu?","Pārbaudot, pamanāt skaidri saliektu zaru.","Ja iespējams, sadaliet slodzi uz otru zaru.","Līdz nākamajai apkopei brauciet tikai ar vieglu kravu.","Neizmantojiet iekrāvēju un ziņojiet par defektu atbildīgajai personai.","Bojāta kravas pārvietošanas iekārta var sabojāties; Drošībai nozīmīgi defekti ir jāizslēdz, līdz tie tiek noskaidroti."],"g-einweisung":["Jūs pārslēdzaties uz iekrāvēju ar dažādām vadības ierīcēm. Kas nepieciešams pirms lietošanas?","Darbība atšķiras no jūsu iepriekšējā transportlīdzekļa.","Ar ierīci saistīta instrukcija un atbilstība lietošanas instrukcijai.","Vienmēr pietiek ar īsu paskaidrojumu no neiesaistīta kolēģa.","Nav papildu informācijas, ja jums ir autokrāvēja licence.","Vispārēja kvalifikācija neaizstāj nepieciešamos norādījumus par faktiski izmantoto ierīci."],"g-anbaugeraet":["Jums vajadzētu izmantot pielikumu. Ko jūs vispirms pārbaudāt?","Jauns aprīkojums maina kravas uzņemšanas veidu.","Vai agregāts atbilst transportlīdzekļa apstiprinājumam un pieļaujamajai slodzei.","Tikai vai ierīci var vizuāli piestiprināt.","Vai pielikumu var uzstādīt bez dokumentācijas.","Pielikumi var mainīt atlikušo kravnesību un kravas centru; Jāpārbauda apstiprinājumi un kravnesības informācija."],"g-diagramm":["Kāpēc jums ir nepieciešama kravnesības diagramma?","Ir liela slodze ar smaguma centru tālu uz āru.","Lai noteiktu īsāko maršrutu.","Novērtēt maksimāli pieļaujamo slodzi atkarībā no pacelšanas augstuma un kravas centra.","Lai noteiktu tvertnes tilpumu.","Pieļaujamās slodzes, cita starpā, ir atkarīgas no kravas centra attāluma un pacelšanas augstuma."],"g-lastschwerpunkt":["Kas parasti notiek, kad smaguma centrs virzās tālāk uz priekšu?","Dakšu priekšā tālu izvirzās gara krava.","Pieļaujamā kravnesība var samazināties.","Nestspēja vienmēr palielinās.","Attālumam nav ietekmes uz apgāšanās momentu.","Lielāks attālums no kravas centra palielina apgāšanās momentu un var samazināt pieļaujamo kravnesību."],"g-gabelabstand":["Kā dakšām vajadzētu uzņemt piemērotu paleti?","Jūs vēlaties uzņemt vienmērīgi piekrautu paleti.","Ar zariem pēc iespējas tuvāk un tikai uz viena stūra.","Ar tik lielu attālumu, ka palete apgāžas uz sāniem.","Ar piemērotu zaru attālumu un pietiekamu šasiju un atbalsta laukumu.","Krava ir jāatbalsta droši un pēc iespējas vienmērīgāk pāri dakšām."],"g-schieflast":["Krava ir sakrauta nestabili. Kas ir pareizi?","Paceļot kartona kastes var nokrist.","Sāciet lēnām; lādiņš pats nostabilizējas.","Pirms kravas paņemšanas to pietiekami nostipriniet vai lieciet no jauna salikt.","Paceliet kravu virs galvas augstuma, lai tā netraucētu.","Irdena vai nestabila krava var nokrist un apdraudēt cilvēkus; vispirms veiciet drošības pasākumus."],"g-personen":["Vai cilvēku var pacelt uz parastajām dakšām?","Kolēģis vēlas sasniegt gaismu.","Jā, ja kolēģis nēsā ķiveri.","Nē, cilvēki drīkst izmantot tikai tam paredzētās un atļautās telpas saskaņā ar īpašām prasībām.","Jā, ja tuvojas tikai nelielam augstumam.","Parastās dakšas nav personīga darba platforma; Cilvēku pārvadāšanai un celšanai ir noteiktas īpašas prasības."],"g-transporthoehe":["Kā jūs parasti transportējat paleti?","Ceļš ir skaidrs un līdzens.","Ar paceltu kravu tikai tik tālu, cik nepieciešams un saskaņā ar lietošanas instrukciju.","Ar kravu paceltu pēc iespējas augstāk, lai būtu labāk redzams.","Ar pacelšanas mastu, kas ir stipri sasvērts uz priekšu, neatkarīgi no kravas.","Zema transportēšanas pozīcija samazina apgāšanās un sadursmes risku; Ierīces norādījumi ir izšķiroši."],"g-kurvenfahrt":["Kāpēc ātri izbraukt pagriezienus ar autoiekrāvēju ir bīstami?","Jūs vēlaties ātri iziet no šauras takas.","Jo tas vienkārši ātrāk iztukšo akumulatoru.","Jo iekrāvējs automātiski stūrē labāk.","Tā kā sānu spēki ietekmē stabilitāti un var izraisīt apgāšanos.","Izbraucot līkumus, iedarbojas papildu spēki; ātrums ir jāpielāgo slodzei un apstākļiem."],"g-ladebruecke":["Ko jūs pārbaudāt pirms uzbraukšanas uz iekraušanas tilta?","Jums vajadzētu braukt ar kravas automašīnu.","Tikai vai ceļš izskatās pietiekami plats.","Kravnesība, drošs atbalsts un aizsardzība pret pārslēgšanu, kā arī transportlīdzekļa nostiprināšana.","Tikai vai apgaismojums ir ieslēgts.","Iekraušanas tiltiem un transportlīdzekļiem jābūt nodrošinātiem pret kustību un piemērotiem kravai."],"g-fussgaenger":["Kā tu uzvedies mulsinošā krustojumā ar gājējiem?","Vizuālie savienojumi ir ierobežoti.","Brauciet ar atbilstošu ātrumu, ja nepieciešams, apstājieties un nodrošiniet drošu redzamību.","Vienmēr pieprasiet priekšroka tiesības, pārvadājot kravu.","Vienkārši pasauc un turpini braukt.","Gājējiem ir īpašas aizsardzības vajadzības; Ātrums, redzamība un komunikācija ir jāpielāgo satiksmes maršrutam."],"g-batterieladen":["Kam jāpievērš īpaša uzmanība, uzlādējot piedziņas akumulatoru?","Tiek izmantota akumulatora uzlādes stacija.","Uzlādes vietu var izvēlēties neatkarīgi no ražotāja norādījumiem.","Atklāta liesma ir atļauta, kamēr iekrāvējs stāv.","Piemērota iekraušanas zona, pietiekama ventilācija un ražotāja specifikācijas, kā arī uguns un sprādziena aizsardzība.","Uzlādes laikā apdraudējumu var radīt elektriskā enerģija, gāzes un ķīmiskās vielas; ir jāievēro paredzētie aizsardzības pasākumi."],"h-beauftragt":["Ar kādiem nosacījumiem jūs drīkstat patstāvīgi vadīt pacēlāju darba platformu?","Jums vajadzētu izmantot darba platformu uzņēmumā.","Ja jums ir automašīnas vadītāja apliecība.","Ja esat piemērots, esat instruēts vai kvalificēts un darba devēja pasūtījis.","Ja kādreiz esat redzējis darba platformu.","Darba devējam jānodrošina atbilstība, kvalifikācija un norīkojumi atbilstoši darbības prasībām."],"h-vorpruefung":["Kas jāpārbauda pirms darba uzsākšanas ar paceļamo darba platformu?","Pa nakti skatuve bija ārā.","Vizuāla un funkcionāla pārbaude saskaņā ar ražotāja norādījumiem, ieskaitot drošības ierīces.","Tikai skatuves krāsa un vecums.","Vai darba materiāls jau ir uz platformas.","Pirms lietošanas mašīna, vadības ierīces, avārijas funkcijas un redzami bojājumi ir jāpārbauda saskaņā ar lietošanas instrukciju."],"h-tragfaehigkeit":["Kāda informācija nosaka pieļaujamo slodzi uz darba grozu?","Divi cilvēki vēlētos ņemt līdzi papildu rīkus.","Cilvēki var brīvi novērtēt pieļaujamo kopējo svaru.","Svarīgs ir tikai smagākā cilvēka svars.","Nedrīkst pārsniegt cilvēku, instrumentu un materiālu kravnesības specifikāciju.","Nominālā slodze attiecas uz kopējo pieļaujamo slodzi, ieskaitot visus pārvadājamos materiālus."],"h-untergrund":["Ko jūs apsverat, pirms uzstādāt skatuvi ar balstiem?","Jūs strādājat tuvu aizpildītai zonai.","Tikai uzplaukuma sasniedzamā attālumā.","Pārbaudiet pamatnes nestspēju un līdzenumu, kā arī piemērotu balstu saskaņā ar instrukcijām.","Par mazāko iespējamo paplašināto balstu skaitu.","Nepietiekama zeme vai nepareizs atbalsts var izraisīt stabilitātes zudumu."],"h-wind":["Pūš stiprs vējš. Kā jūs to darāt?","Jūs atrodaties ar āra skatuvi.","Ievērojiet ražotāja noteiktos ierobežojumus un, ja tie tiek pārsniegti, pārtrauciet darbību vai droši nolaidiet grozu.","Izstiepiet platformu pēc iespējas tālāk, lai tā būtu stabilāka.","Reaģējiet tikai tad, ja nokrīt vaļīgi priekšmeti.","Ražotāja atļautie vēja apstākļi ir lietošanas ierobežojumi; Vējš var radīt bīstamus papildu spēkus."],"h-strom":["Jums jāstrādā pie gaisvadu elektrolīnijas. Kas ir izšķirošs?","Darba zonā ir dzīva līnija.","Ķivere aizstāj drošas distances ievērošanu.","Vienkārši izolējiet grozu un strādājiet bez koordinācijas.","Noskaidrojiet bīstamo zonu un nodrošiniet nepieciešamos aizsargattālumus vai citus piemērotus pasākumus.","Elektriskā pārslēgšanās iespējama arī bez tieša kontakta; Pirms operācijas uzsākšanas jānosaka nepieciešamie aizsardzības pasākumi."],"h-notablass":["Kāpēc ir jāzina avārijas nolaišanas procedūra?","Iespējama parastās vadības kļūme.","Lai darbības traucējumu gadījumā būtu iespējama droša glābšana saskaņā ar ierīci.","Lai ierīce normālā darbībā darbotos ātrāk.","Lai aizstātu regulāras pārbaudes.","Pirms lietošanas avārijas vadības ierīcēm, avārijas nolaišanas un glābšanas koncepcijām jābūt zināmām un funkcionālām."],"h-gelaender":["Kā panākt papildu augstumu darba grozā?","Montāžas punkts jums nav sasniedzams.","Uzkāpiet uz grozu žoga.","Novietojiet dēli uz margām.","Izmantojiet piemērotu platformu ar pietiekamu darba augstumu; kāpt uz margām.","Kāpšana pa žogu vai improvizēti paaugstinājumi apdraud aizsardzību pret kritienu."],"h-psaga":["Kādas prasības attiecas uz individuālajiem kritienu aizsarglīdzekļiem?","Jūs izmantojat darba platformu, kurai ir paredzēta ierobežotājsistēma.","Vienmēr pietiek ar jebkuru enkura punktu ārpus groza.","Ievērojiet riska novērtējumu, ražotāja norādījumus un piemērotos stiprinājuma punktus.","Neizmantojiet drošības līdzekļus, ja grozam ir margas.","To, vai un kādi IAL ir nepieciešami, nosaka riska novērtējums, skatuves uzbūves un ekspluatācijas instrukcija."],"h-verfahren":["Vai skatuvi var pārvietot ar paceltu platformu?","Darba vieta atrodas dažu metru attālumā.","Tikai tad, ja modelis un ekspluatācijas apstākļi to atļauj saskaņā ar ražotāja norādījumiem.","Vienmēr, kamēr visi turas.","Nē, nekad neatkarīgi no konstrukcijas un ražotāja apstiprinājuma.","Kustība paceltā stāvoklī ir atkarīga no ierīces un ir atļauta tikai apstiprinātajos ekspluatācijas apstākļos."],"h-kollision":["Kas jāorganizē, strādājot pie celtņiem vai citām mašīnām?","Kustīgās daļas var sasniegt darba grozu.","Nekas; darba grozs vienmēr ir redzams.","Vienmēr brauciet ar darba grozu pāri citām mašīnām.","Saskaņojiet darba zonas, lai izvairītos no sadursmēm vai saspiešanas punktiem.","Vienlaicīgai mašīnas darbībai ir nepieciešami koordinēti darba procesi un aizsardzība pret sadursmēm vai iesprūšanu."],"h-einstieg":["Kā ieiet vai iziet no darba groza?","Jūs sasniedzat grozu zemes līmenī.","Kāpt pāri ārējām margām.","Pa paredzēto piekļuvi drošā vietā saskaņā ar lietošanas instrukciju.","Caur kāpnēm, kas novietotas blakus ar izstieptu izlici.","Jāievēro paredzētās piekļuves un ražotāja norādījumi; Nekontrolēta kāpšana pāri rada kritiena risku."],"h-defekt":["Avārijas apstāšanās iekārta nedarbojas. ko tu dari?","Pārbaudes laikā jūs atklāsiet defektu.","Neizmantojiet platformu un ziņojiet par defektu.","Turpiniet strādāt, ja darbojas parastās vadības ierīces.","Pielīmējiet slēdzi ar līmlenti, lai neviens to nedarbinātu.","Drošības ierīces atteice ir ar drošību saistīts defekts, kas neļauj droši darboties."],"h-sicht":["Braukšanas kustību nevar redzēt šķēršļa dēļ. Kā jūs to darāt?","Jums vajadzētu pārvietot mobilo skatuvi.","Brauciet lēni bez redzamības.","Vienkārši paļaujieties uz attāluma indikatoru.","Apturiet kustību un nodrošiniet redzamību vai drošu norādījumu saskaņā ar lietošanas instrukciju.","Pirms procedūras droši jāapseko cilvēki, šķēršļi un satiksmes ceļi."],"h-rettung":["Ko ietver izvietošanas plānošana, strādājot lielākā augstumā?","Skatuve tiek izmantota nomaļā vietā.","Tikai plānotais darba ilgums.","Piemērota glābšanas koncepcija ar pieejamiem, apmācītiem cilvēkiem un avārijas nolaišanas procedūrām.","Pieņēmums, ka ugunsdzēsēji nekavējoties atrisinās jebkuru problēmu.","Efektīva glābšana ir jāorganizē iepriekš, pat ja parastās vadības ierīces neizdodas."],"k-befaehigung":["Kas nepieciešams, lai patstāvīgi darbinātu celtni?","Paredzēts, ka celtņa darbu pārņems jauns darbinieks.","Atbilstība un nepieciešamā kvalifikācija, instruktāža un atbilstošs uzdevums.","Pietiek ar auto vadīšanas tiesībām.","Pietiek ar vienu noskatīšanos.","Celtņa darbus drīkst uzdot tikai kvalificētām un pilnvarotām personām; Aprīkojuma instrukcija ir daļa no tā."],"k-funktionspruefung":["Kas nepieciešams, lai pārbaudītu celtni pirms maiņas sākuma?","Jūs pārņemat iekštelpu celtni.","Vienkārši izlasiet darbības laiku uz datu plāksnītes.","Pārbaudiet ar drošību saistītās funkcijas un redzamos defektus saskaņā ar lietošanas instrukciju.","Pārbaudiet celtni ar maksimālo slodzi bez pārbaudes.","Obligātā ekspluatācijas kontrole kalpo, lai agrīnā stadijā identificētu bīstamus defektus."],"k-traglast":["Kāda ir pieļaujamās kravnesības nozīme?","Jāceļ krava.","Tas ir nesaistošs ieteikums.","Tas ir spēkā tikai tad, kad āķis ir pilnībā ievilkts.","Nedrīkst pārsniegt attiecīgajam ekspluatācijas stāvoklim pieļaujamo kravnesību.","Pieļaujamās slodzes noteiktiem celtņu veidiem var būt atkarīgas no rādiusa, izlices stāvokļa un bruņojuma."],"k-personen":["Kas attiecas uz cilvēkiem, kas atrodas zem piekārtas kravas?","Krava tiek pārvietota pa darba zonu.","Bīstamajai zonai jābūt brīvai; neviens nedrīkst pakāpties zem piekārtās kravas.","Ķivere ļauj jums palikt tieši zem tās.","Īsi krustojumi ir atļauti, ja celtnis pārvietojas lēni.","Piekārtas kravas rada krišanas un saspiešanas risku; Cilvēki nedrīkst atrasties bīstamajā zonā."],"k-signale":["Jūs nevarat redzēt uzbrucēju un saņemat pretrunīgus signālus. ko tu dari?","Komunikācija ir neskaidra.","Turpiniet pēdējo diska komandu.","Pārtrauciet kustību un skaidri noskaidrojiet saziņu.","Nolieciet kravu ātrāk, bez konsultēšanās.","Drošām kravas kustībām ir nepieciešami skaidri signāli un skaidra saziņa."],"k-sicht":["Kurš sniegs atbalstu transportēšanas laikā, ja celtņa operators nevar pilnībā redzēt kravas ceļu?","Priekšnama stabs aizsedz ceļu.","Cilvēks, kurš pagadās garām bez iepriekšējas vienošanās.","Neviens; svarīgs ir tikai āķis.","Piemērota, instruēta persona ar skaidri saskaņotu izpratni.","Ja kravas ceļš nav redzams, ir nepieciešama atbilstoša instrukcija vai cits drošs risinājums."],"k-ruck":["Kāpēc vajadzētu izvairīties no saraustītām celtņa kustībām?","Sāk šūpoties smaga slodze.","Tie rada papildu dinamiskus spriegumus un var destabilizēt slodzi.","Tie būtībā samazina jebkuru svārsta kustību.","Tie vienmēr palielina nominālo kravnesību.","Paātrinājuma un bremzēšanas spēki palielina celtņa un stropu slodzi."],"k-sperrbereich":["Kas jāpārbauda pirms kravas šūpošanas koplietošanas zonā?","Blakus strādā citi darbinieki.","Vai krava vizuāli sakrīt ar celtni.","Vai bīstamā zona ir nodrošināta un neviens cilvēks nav apdraudēts.","Vai kravu var nest pēc iespējas augstāk pāri visiem.","Pagrieziena un kravas ceļiem jābūt brīviem no neaizsargātiem cilvēkiem."],"k-stuetzen":["Kas ir būtisks mobilajam celtnim ar balstiem?","Uz daļēji piepildītas zemes tiek novietots celtnis.","Tikai ceļa platumā.","Atbalsta plākšņu krāsa.","Nesošā pamatne, kā arī balsts un slodzes sadalījums saskaņā ar uzstādīšanas un ražotāja norādījumiem.","Uzstādīšanai ir būtiska ietekme uz stabilitāti, īpaši mainīgos zemes apstākļos."],"k-wetter":["Vēja brāzma izraisa kravas ievērojamu šūpošanos. Kas ir pareizi?","Jūs strādājat ārā.","Droši apturiet kustību un ievērojiet pieļaujamos ekspluatācijas nosacījumus.","Ātri paātriniet kustību.","Turpiniet pacelt kravu, neskatoties uz ražotāja noteikto ierobežojumu pārsniegšanu.","Vēja un šūpošanās kustības var destabilizēt kravu un celtni; Jāievēro pieteikšanās ierobežojumi."],"k-freileitung":["Kas attiecas uz celtņu izmantošanu gaisvadu elektrisko līniju tuvumā?","Izlice vai krava var tuvoties līnijai.","Ar nevadošu slodzi atstarpes nav svarīgas.","Pirms darba uzsākšanas noskaidrojiet bīstamo zonu un nepieciešamos aizsardzības pasākumus ar atbildīgajiem.","Paļaujieties tikai uz paša celtņa operatora reakciju.","Pastāv draudi, ko rada kontakta un sprieguma pārslēgšanās; ir nepieciešami droši aizsargattālumi vai citi pasākumi."],"k-sichern":["Ko jūs darāt, pirms pametat celtni?","Darbs tiek pārtraukts.","Ļaujiet kravai karāties piekārtai.","Atstājiet celtni bez uzraudzības, piedziņai darbojoties.","Droši nolaidiet kravu un nostipriniet celtni saskaņā ar lietošanas instrukciju.","Piekārtās kravas nedrīkst atstāt nekontrolētas; Celtnis un krava ir jānovieto droši."],"k-lastanschlag":["Kā zināt, vai izmantotā strope ir piemērota?","Krava jāpaceļ, izmantojot pacelšanas siksnu.","Marķējuma, kravnesības, stāvokļa un atbilstības stiprinājuma veidam ziņā.","Tikai pēc pacelšanas siksnas krāsas.","Jo vakar jau tika lietots.","Kravnesībai un stāvoklim jābūt pietiekamam, ņemot vērā stiprinājuma nosacījumus."],"k-stopp":["Cilvēks negaidīti ieiet slodzes ceļā. ko tu dari?","Pašlaik celtnis pārvieto kravu.","Nekavējoties droši pārtrauciet kustību un atbrīvojiet bīstamo zonu.","Vienkārši dodiet brīdinājuma signālu un turpiniet braukt.","Paceliet kravu augstāk un brauciet tai pāri.","Cilvēki ir jāaizsargā no kravas kustībām; Ja pastāv tūlītējas briesmas, kustība ir jāpārtrauc."],"k-neuerkran":["Jūs saņemsiet celtni ar nezināmu vadību. Kas ir pareizi?","Vadības elementi atšķiras no iepriekšējiem.","Ja jums ir aizdomas, izmēģiniet parastās atslēgas.","Ļaujiet kādam citam bez apmācības braukt uz priekšu.","Pirms neatkarīgas lietošanas saņemiet nepieciešamos norādījumus par ierīci.","Pat pieredzējušiem celtņu operatoriem ir vajadzīgas zināšanas par īpašajām izmantotajām vadības ierīcēm, aizsargierīcēm un ierobežojumiem."],"a-kennzeichnung":["Kā zināt stropes pieļaujamo kravnesību?","Jūs vēlaties izvēlēties slingu.","Materiāla smarža.","Par atbilstošu, salasāmu kravnesības marķējumu un ražotāja informāciju.","Par uzglabāšanas laika ilgumu.","Pieļaujamo kravnesību nosaka marķējums un ekspluatācijas apstākļi."],"a-sichtpruefung":["Jūs pamanāt skaidru griezumu pacelšanas siksnā. Kā jūs to darāt?","Joslai ir jānes slodze.","Neizmantojiet lenti un nenosūtiet to pārbaudei vai noraidīšanai.","Pārklājiet griezumu ar lenti.","Izmantojiet to tikai īpaši vieglām kravām.","Bojātas tekstila stropes var sabojāties, un tās ir jānovērtē saskaņā ar izmešanas kritērijiem."],"a-neigungswinkel":["Kas notiek, ja stropes šķipsnu slīpuma leņķis ir lielāks par vertikāli?","Divu šķipsnu pakaramais izplešas vairāk.","Stiepes spēki vienmēr samazinās.","Stiepes spēki paliek nemainīgi.","Spēki dzīslās palielinās; Jāievēro pieļaujamie leņķi un kravnesība.","Palielinoties izkliedei, palielinās stiepes spēks uz vienu atbalsta šķipsnu."],"a-schwerpunkt":["Kāpēc jums jāzina kravas smaguma centrs?","Slodze tiek veidota nevienmērīgi.","Lai krava paceļot paliktu stabila un nekontrolējami neapgāztos.","Lai izvēlētos stropu krāsu.","Lai kravu varētu pagriezt ātrāk.","Nelabvēlīgi stiprinājuma punkti vai smaguma centra novietojums var izraisīt apgāšanos, slīdēšanu vai slīpumu."],"a-kantenschutz":["Pacelšanas siksna atrodas pret asu detaļas malu. Kas būtu jādara?","Komponents ir jāpaceļ.","Ātri paceliet kravu, pirms josta nav bojāta.","Izmantojiet piemērotu malu aizsardzību un pārbaudiet stiprinājuma veidu.","Tīriet kravas virsmu tikai ar drānu.","Asas malas var sabojāt atbalsta šķiedras; stropu aprīkojums ir attiecīgi jāaizsargā."],"a-haken":["Kam pievēršat uzmanību, piestiprinot slingu?","Jūs izmantojat kravas āķi.","Novietojiet stropu āķa gala malā.","Turiet drošības atloku pastāvīgi atvērtu.","Ievietojiet āķi āķa pamatnē, kā paredzēts, un ievērojiet drošības ierīces.","Nepieļaujama slodze uz āķa galu un stiprinājuma trūkums var novest pie tā atkabināšanas."],"a-knoten":["Vai jūs varat saīsināt pārāk garu pacelšanas siksnu ar mezglu?","Pieturas garums neatbilst.","Nē; Izmantojiet tikai piemērotu, apstiprinātu stropes veidu vai piemērotu stropes aprīkojumu.","Jā, ja mezgls ir pievilkts ļoti cieši.","Jā, kamēr krava šobrīd nekustas.","Mezgli var ievērojami vājināt tekstila stropes, un tiem nav atļauta improvizēta garuma regulēšana."],"a-probehub":["Kāpēc krava sākotnēji tiek pacelta uzmanīgi?","Jūs vēlaties transportēt droši.","Lai viņa varētu pēc iespējas ātrāk doties ceļā.","Lai pārbaudītu stropu stāvokli, stabilitāti un smaguma centru.","Jo kravnesība palielinās automātiski.","Kontrolēts pirmais gājiens palīdz noteikt nepareizas apstāšanās un nestabilas kravas pozīcijas."],"a-lastweg":["Kur cilvēkiem ir atļauts uzturēties kravas transportēšanas laikā?","Kravu pārvieto ar celtni.","Tieši zem kravas ar aizsargķiveri.","Uz nastu, ja viņi var noturēties.","Ārpus bīstamās zonas un ne zem piekārtas kravas.","Pat ar rūpīgu piestiprināšanu joprojām pastāv briesmas, ko rada krītoša vai šūpojoša slodze."],"a-haende":["Kā izvairīties no saspiešanas traumām atšķiršanas laikā?","Slodze tuvojas atbalsta virsmai.","Neturiet rokas un kājas no saspiešanas zonas un izmantojiet atbilstošus palīglīdzekļus.","Turiet kravu ar kailu roku.","Stāviet starp kravu un sienu, lai labotu pozīciju.","Starp kravu un balstu rodas bīstami saspiešanas punkti."],"a-vierstraenge":["Kas attiecas uz slodzes sadalījumu uz četrkāju balstiekārtu bez slodzes kompensācijas?","Ir piestiprināta stingra slodze.","Visās četrās daļās neizbēgami ir vienāds daudzums.","Ja nav pierādījumu par vienmērīgu sadalījumu, nestspēju nevar izmantot kā vispārīgu novērtējumu četrām vienādi noslogotām dzīslām.","Tad slīpuma leņķim nav nozīmes.","Ar stingrām slodzēm iespējama nevienmērīga dzīslu slodze; Tas ir jāņem vērā, izstrādājot konstrukciju un pieļaujamo kravnesību."],"a-chemikalien":["Kas attiecas uz tekstila stropu lietošanu saskarē ar ķīmiskām vielām?","Jūs strādājat ar nezināmu šķidrumu.","Lentes krāsa droši parāda tās izturību.","Katra tekstila josla ir izturīga pret visām ķīmiskajām vielām.","Pārbaudīt izturību un ražotāja informāciju; Neizmantojiet nepiemērotus līdzekļus.","Ķīmiskās vielas var uzbrukt stropēm un nepamanīti samazināt to nestspēju."],"a-aufbewahrung":["Kā stropes tiek uzglabātas pēc lietošanas?","Misija ir beigusies.","Tīra, sausa un aizsargāta pret bojājumiem saskaņā ar ražotāja specifikācijām.","Iestrēdzis uz zemes zem neaizsargātas slodzes.","Uz jebkura asa āra āķa.","Pareiza uzglabāšana novērš priekšlaicīgu nodilumu un atvieglo vizuālo pārbaudi."],"a-auswahl":["Kam jāpievērš īpaša uzmanība, strādājot ar jutīgām vai asām kravām?","Krāsota mašīnas sastāvdaļa ir jāpārvieto.","Tikai transporta ātrums.","Piemērotas stropes un aizsargpasākumi kravas virsmai un malām.","Neatkarīgi no slodzes vienmēr viens un tas pats tērauda kabelis.","Piestiprinājuma veidam un materiālam jāatbilst ģeometrijai, virsmai un bīstamībai."],"a-abstimmung":["Celtņa operatoram jūs neredzat. Kā jūs sniedzat norādījumus?","Jūs esat iecelts kā uzbrucējs.","Jūs vicināt pēc vēlēšanās, līdz sākas kustība.","Vienkārši piezvani un ej prom.","Izmantojot skaidri saskaņotas zīmes vai citu uzticamu saziņu.","Uzbrucējiem un celtņu operatoriem jāsazinās skaidri; Ja nav skaidrs, kustība ir jāpārtrauc."],"b-qualifikation":["Kas cilvēkam ir nepieciešams, lai darba laikā droši darbinātu hidraulisko ekskavatoru?","Būvlaukuma darbus vajadzētu pārņemt jaunam cilvēkam.","Atbilstoša kvalifikācija, ar ierīci saistītas instrukcijas un nepieciešamais uzdevums.","Tikai automašīnas vadīšanas tiesības.","Tikai ātrs operācijas novērojums.","Darba devējam jānodrošina nepieciešamā kvalifikācija un atbilstoši jāinstruē operators uzdevuma veikšanai."],"b-pruefung":["Kas ir iekļauts ikdienas mašīnas pārbaudē?","Jūs pārņemat ekskavatoru.","Pārbaudiet krāsas krāsu un sēdekļa polsterējumu.","Vizuāla pārbaude un funkcionālās pārbaudes saskaņā ar lietošanas instrukciju, piemēram, vai nav noplūžu un bojājumu.","Pārvietojiet izlici pilnā ātrumā, līdz tā apstājas.","Hidraulikas, šasijas un drošības ierīču bojājumi var izraisīt nopietnus negadījumus."],"b-leitungen":["Kas jāzina par pazemes caurulēm pirms rakšanas?","Vajadzētu rakt grāvi.","Tikai plānotās rakšanas bedres aptuvenais dziļums.","Virszemes marķējuma krāsa ir pietiekama.","Precizēt iespējamo līniju atrašanās vietu un noteikt piemērotus drošības un izpētes pasākumus.","Elektrības, gāzes vai ūdensvadu bojājumiem var būt dzīvībai bīstamas sekas."],"b-schwenkbereich":["Kā jūs aizsargājat cilvēkus ekskavatora šūpoļu zonā?","Jūs uzņemat materiālu ar strēli.","Norobežojiet vai nostipriniet bīstamo zonu un turiet prom cilvēkus.","Pirms pagriešanas lēnām pārvietojiet lāpstu.","Brauciet pāri teritorijai virs galvām.","Grozāmā virsbūve un darba aprīkojums rada saspiešanas un trieciena risku."],"b-boeschung":["Kas ir svarīgi, strādājot netālu no rakšanas bedres malas?","Ekskavators stāv uz izveidotas vai aizpildītas zemes.","Tikai rakšanas dziļums nosaka pieļaujamo novietojumu.","Pievērsiet uzmanību nestspējai un malas nostiprināšanai, kā arī nepieciešamajiem attālumiem atbilstoši riska novērtējumam.","Lai saglabātu attālumu, brauciet pēc iespējas tuvāk malai.","Ja nav pietiekama klīrensa vai stabila zeme, uzbērums var sabojāties un mašīna var nokrist."],"b-standsicherheit":["Kāpēc nogāzei un zemei ​​ir izšķiroša nozīme?","Būvlaukums atrodas nogāzē.","Mašīna ir vienlīdz stabila uz jebkuras virsmas.","Kāpurķēžu šasijas novērš jebkādu apgāšanās risku.","Nelīdzenumi un nogāzes var ietekmēt stabilitāti; Ievērojiet lietošanas ierobežojumus.","Stabilitāte un apgāšanās drošība ir atkarīga no grīdas, aprīkojuma, kravas un mašīnas stāvokļa."],"b-wechselgeraet":["Ko pārbaudāt pēc ekskavatora kausa nomaiņas, izmantojot ātro savienotāju?","Tika instalēts jauns pielikums.","Vai tas ir pareizi aizslēgts un nostiprināts saskaņā ar lietošanas instrukciju.","Tikai vai lāpstas krāsa sakrīt.","Vai hidraulika darbojas pēc iespējas klusāk.","Bojātas slēdzenes var izraisīt pielikumu nokrišanu."],"b-heben":["Kam jāpievērš uzmanība, paceļot ar ekskavatoru brīvi nokarenu kravu?","Ekskavatoru izmanto celšanas operācijām.","Izšķirošs ir tikai parastais rakšanas spēks.","Ievērojiet pieļaujamo celšanas slodzi, piemērotos stiprinājuma punktus un paredzētos aizsargierīces.","Kravu var piestiprināt pie kausa zobiem.","Pacelšana ir atļauta tikai paredzētajos ekspluatācijas apstākļos ar piemērotu aprīkojumu."],"b-rueckwaerts":["Jums ir jābrauc atpakaļgaitā, bet jūs nevarat redzēt ceļu. Kas ir pareizi?","Blakus ir citi strādnieki.","Brauciet uzmanīgi bez redzamības.","Vienkārši pasauc un turpini braukt.","Apstāties, nodrošināt redzamību un bīstamo zonu vai organizēt atbilstošus norādījumus.","Braukšana atpakaļgaitā nedrīkst apdraudēt cilvēkus; ierobežotai redzamībai nepieciešami papildu pasākumi."],"b-kabel":["Izlice varētu pietuvoties gaisvadu elektrolīnijai. ko tu dari?","Jūs strādājat saspringtā būvlaukumā.","Pirms tam ar atbildīgajām personām noskaidrojiet bīstamo zonu un piemērotus aizsardzības pasākumus.","Ignorējiet līniju, ja izlice ir nokrāsota.","Pārvietojiet izlici tikai īpaši ātri.","Elektrības apdraudējumi rodas no saskares un uzliesmojuma; ir nepieciešami droši attālumi un aizsardzības pasākumi."],"b-verlassen":["Kā novietot ekskavatoru pirms izbraukšanas?","Jūs paņemat pārtraukumu.","Atstājiet strēli brīvi peldēt.","Droši novietojiet darba aprīkojumu un nodrošiniet to pret pārvietošanos un neatļautu lietošanu.","Atstājiet dzinēju darboties un kabīni atvērtu.","Nolaists darba aprīkojums un aizsardzība pret netīšu pārvietošanos samazina nelaimes gadījumu risku."],"b-hydraulik":["Jūs pamanāt, ka uz bojātas līnijas hidrauliskā eļļa ir zem augsta spiediena. Kas ir pareizi?","Noplūst līnija.","Sajūti noplūdi ar roku.","Piestipriniet jaunu skavu zem spiediena.","Droši izslēdziet iekārtu, ļaujiet samazināt spiedienu un noorganizējiet remontdarbus, ko veic pilnvarots speciālists.","Hidrauliskais šķidrums zem augsta spiediena var izraisīt nopietnas traumas; nekad nepārbaudiet noplūdes ar roku."],"b-unterbau":["Kādas ir briesmas, braucot pa nestabilām virsmām?","Zeme pēc lietus ir mīksta.","Mašīna var nogrimt, slīdēt vai apgāzties.","Disks automātiski kļūst platāks.","Tas padara grozāmo diapazonu drošāku.","Nepietiekama kravnesība var būtiski pasliktināt stabilitāti un braukšanas drošību."],"b-arbeitsgeraet":["Vai kāds var strādāt zem pacelta agregāta?","Cilvēks vēlas kaut ko kontrolēt zem lāpstas.","Jā, kad dzinējs darbojas tukšgaitā.","Nē, ne bez nepieciešamā droša atbalsta un darba aprīkojuma nostiprināšanas.","Jā, ja persona valkā aizsargķiveri.","Hidrauliskās iekārtas var nogrimt; Apkopes darbiem nepieciešams drošs darba aprīkojums."],"b-geraeteart":["Jūs pārejat no hidrauliskā ekskavatora uz riteņu iekrāvēju. Kas ir nepieciešams?","Darbības un kustību uzvedība atšķiras.","Tikai tie paši apavi.","Izmēģinājuma brauciens bez instrukcijām.","Kvalifikācija vai instrukcija, kas nepieciešama jaunajam mašīnas tipam.","Kvalifikācijai jāatbilst izmantotās mašīnas tipam un īpašajām ekspluatācijas prasībām."],"g-neigung":["Jūs braucat ar piekrautu iekrāvēju uz nogāzes. Kas ir svarīgi?","Maršrutam ir skaidrs slīpums.","Vienmēr virziet kravu lejup, pat ja tā ir smaga.","Virziet kravu kalnup un ievērojiet ekspluatācijas norādījumus, braucot pa slīpumiem.","Neatkarīgi no braukšanas virziena paceliet dakšu līdz maksimumam.","Uz kāpumiem un nobraucieniem krava vienmēr jānes augšup; Jāievēro transportlīdzeklis un lietošanas instrukcija."],"g-gabelabsenken":["Kāpēc novietojot automašīnu stāvēšanai, dakša ir jānolaiž?","Iekrāvējs ir novietots uz pārtraukumu.","Lai citi varētu izmantot dakšu, lai kāpt augšā.","Lai dakša paliek labāk redzama no attāluma.","Lai kravas celšana neradītu nevajadzīgu paklupšanas vai savainojumu risku.","Nolaistās kravas pārtīšanas ierīces samazina negadījumu risku izvirzītu vai nenostiprinātu dakšu dēļ."],"g-fahrerwechsel":["Kolēģe vēlētos aizņemties autokrāvēju. Kam jābūt klāt?","Kolēģim ir tikai mutiska atļauja no jums.","Viņam ir jābūt vajadzīgajai kvalifikācijai un darbības mandātam.","Jūsu uzdevums automātiski attiecas arī uz viņu.","Katram uzņēmumam pietiek ar privātās automašīnas vadītāja apliecību.","Neatkarīga vadība ir saistīta ar personīgo piemērotību, apmācību, kvalifikāciju un operatīvo uzdevumu."],"g-ladungssicherung":["Paletē ir vaļīgas, sakrautas kastes. Kas ir pareizi?","Kartona kaste braukšanas laikā var nokrist.","Pirms transportēšanas nostipriniet kravu pret slīdēšanu un krišanu.","Pa īpaši nelīdzenu virsmu brauciet tikai lēni.","Kompensējiet vaļīgās kastes ar augstāku dakšu stāvokli.","Pirms kravas transportēšanas ar iekrāvēju, tai jābūt stabilai un nodrošinātai pret krišanu."],"g-bodenbelastung":["Jūsu priekšā ir sega ar ierobežotu nestspēju. Kā jūs izlemjat?","Maršruts ved pāri vidējam līmenim.","Vienkārši pievērsiet uzmanību kravas automašīnas svaram bez kravas.","Noskaidrojiet pieļaujamo grīdas slodzi iekrāvējiem un kravām.","Brauciet ar impulsu, lai griesti būtu zem slodzes īsāku laiku.","Būtisks ir kopējais faktiskais spriegums uz apgabalu, ieskaitot transportlīdzekli, slodzi un dinamiskās ietekmes."],"g-verkehrswege":["Jūsu ceļu šķērso marķēta gājēju celiņa. Kas ir pareizi?","Gājēji pārejai var piekļūt jebkurā laikā.","Jūs vienmēr varat pieprasīt prioritāti ar tauri.","Jums ir atļauts braukt pāri marķējumam, neievērojot.","Pielāgojiet ātrumu, pievērsiet uzmanību gājējiem un turpiniet braukt tikai tad, kad ceļš ir brīvs.","Satiksmes ceļi jābrauc, ņemot vērā cilvēkus; Brīdinājuma zīmes neaizstāj drošu redzamību un skaidru maršrutu."],"g-parkbremse":["Jūs novietojat autoiekrāvēju uz līdzenas zemes. Ko tas ietver?","Jūs vēlaties atstāt vadītāja vietu uz vairākām minūtēm.","Novietojiet automašīnu, ievelciet stāvbremzi un nodrošiniet to pret neatļautu izmantošanu.","Atstājiet automašīnu tikai neitrālā stāvoklī.","Atstājiet dakšiņu galvas augstumā, lai neviens tai nepieskartos.","Pirms izbraukšanas iekrāvējs ir droši jāaptur un jānodrošina pret nejaušu izkustēšanos."],"g-typenschild":["Kura informācija ir saistoša attiecībā uz autoiekrāvēja kravu?","Jūs vēlaties uzņemt smagu mašīnu.","Paredzamā kravnesība, pamatojoties uz transportlīdzekļa izmēru.","Ražotāja informācija slodzes vai kravnesības diagrammā.","Pēdējās transportētās paletes svars.","Pieļaujamo slodzi nosaka ražotāja informācija, un tā cita starpā ir atkarīga no kravas centra un pacelšanas augstuma."],"g-tore":["Jūs tuvojaties zemai ejai ar autokrāvēju. Ko jūs pārbaudāt?","Transportlīdzeklim ir stipra krava.","Vai ir iespējama droša caurbraukšana, ieskaitot kravu un stiprinājumu.","Tikai dakšu turētāju augstums bez kravas.","Vai var ātrāk izbraukt, pirms vārti aizveras.","Pirms ejām jāņem vērā brīvais augstums un platums, kā arī kravas un transportlīdzekļa izmēri."],"g-reifen":["Ikdienas pārbaudē atrodat stipri bojātu riepu. ko tu dari?","Uz riepas ir redzami ar drošību saistīti bojājumi.","Jūs braucat lēni līdz regulārai apkopes apmeklējumam.","Jūs palieliniet riepu spiedienu un turpiniet braukt.","Jūs nedrīkstat nodot transportlīdzekli ekspluatācijā un ziņot par bojājumiem.","Bojātas riepas var pasliktināt stabilitāti un vadāmību; defekts ir jānoskaidro pirms lietošanas."],"h-absperren":["Darbinieki iet garām zem jūsu darba platformas. Kas ir nepieciešams?","Pastāv risks, ka instrumenti krīt.","Piemērota aizsargājoša vai ierobežota zona zem darba vietas.","Tikai paziņojums, kad pirmo reizi ej garām.","Glabājiet instrumentus pēc iespējas tālāk no groza malas.","Darba zonai zem paaugstinātām darba vietām jābūt nodrošinātai pret krītošu daļu radītu apdraudējumu."],"h-werkzeuge":["Kā jūs transportējat instrumentus darba grozā?","Augstumā ir nepieciešami vairāki mazi instrumenti.","Novietojiet tos brīvi uz margām, lai tie būtu viegli sasniedzami.","Glabājiet un nostipriniet tā, lai tie nenokristu un netraucētu darbību.","Piestipriniet pie margu ārpuses kabatā.","Irdeni priekšmeti var nokrist un apdraudēt cilvēkus; nepieciešama droša uzglabāšana."],"h-abstuetzung":["Uz lūkas vāka stāv balsts. Kas ir jāpārbauda?","Jūs vēlaties pacelt platformu.","Vienkārši pārliecinieties, ka vāks ir sauss.","Vai tajā brīdī slodzi var droši uzņemt.","Vai pārējie balsti nav jāizmanto.","Zemei un saskares vietām jāspēj droši absorbēt atbalsta spēkus; Pārsegi jānovērtē atsevišķi."],"h-notaus":["Kad jāizmanto avārijas apturēšanas ierīce?","Tūlīt notiek bīstama kustība.","Tikai parastās maiņas beigās.","Apturēšanai akūtu apdraudējumu gadījumā saskaņā ar lietošanas instrukciju.","Kā aizvietotājs plānotajai nolaišanai.","Avārijas apturēšana tiek izmantota, lai novērstu briesmas, nevis parastā vadība vai parasta izslēgšana."],"h-schraegstellung":["Skatuves slīpuma brīdinājums reaģē. Kā jūs reaģējat?","Mašīna atrodas uz slīpas virsmas.","Jūs ignorējat brīdinājumu zemā darba augstumā.","Neskatoties uz brīdinājumu, jūs braucat uz augstāko pacelšanas pozīciju.","Jūs apstājaties un novietojat skatuvi drošā stāvoklī saskaņā ar ražotāja norādījumiem.","Slīpuma brīdinājumi var norādīt uz nepietiekamu stabilitāti; turpmākās kustības nedrīkst palielināt briesmas."],"h-umgebung":["Kas jāorganizē, uzstādot satiksmes zonas tuvumā?","Transportlīdzekļi var pieskarties skatuvei.","Aizsardzība pret sadursmēm un atbilstoša satiksmes vadība.","Pagrieziet darba grozu pēc iespējas tālāk virs ceļa.","Tikai brīdinājuma zvans pirms palaišanas.","Gaisa darba platformām jābūt aizsargātām pret sadursmēm ar satiksmes dalībniekiem; uzstādīšana ir attiecīgi jānostiprina."],"h-ueberlast":["Tiek iedarbināts groza pārslodzes brīdinājums. ko tu dari?","Tika uzaicināti papildu rīki.","Pabeidziet darbu ar lielāku ātrumu.","Nosakiet pieļaujamo groza slodzi un ievērojiet ražotāja specifikācijas.","Neatgriezeniski izslēdziet brīdinājuma signālu.","Maksimāli pieļaujamo slodzi uz grozu, ieskaitot cilvēkus un materiālus, nedrīkst pārsniegt."],"h-quetschen":["Jūs braucat ar grozu tuvu zem jumta. Kuras briesmas ir īpaši svarīgas?","Virs groza ir maz vietas.","Saspiešana vai saspiešana starp grozu un konstrukciju.","Ka dzinējs patērē vairāk degvielas.","Ka braukšanas virziens vienmēr mainās automātiski.","Šauras vietas virs vai blakus darba grozam var izraisīt nopietnas saspiešanas traumas."],"h-stromausfall":["Skatuve paliek lielā augstumā bez galvenās piedziņas. Kas ir pareizi?","Parastā groza vadība vairs nereaģē.","Jūs bez drošības kāpjat lejā pa strēli.","Jūs gaidāt līdz maiņas beigām, par to neinformējot.","Sāciet sagatavoto glābšanu, izmantojot apmācītus cilvēkus un avārijas nolaišanu.","Pārtraukumu gadījumā jāplāno droša glābšana; Apmācītiem cilvēkiem ir jāzina avārijas funkcijas."],"h-transportstellung":["Kā jūs izveidojat skatuvi transportam?","Gaisa darba platforma ir iekrauta piemērotā transportlīdzeklī.","Novietojiet izlici un platformu transportēšanas stāvoklī saskaņā ar lietošanas instrukciju.","Piesiet platformu pēc iespējas tālāk.","Atstājiet izstieptus balstus, lai tas aizņemtu vairāk vietas.","Noteiktā transportēšanas pozīcija un kravas nostiprināšana ir balstīta uz ražotāja un transportēšanas specifikācijām."],"k-bremsprobe":["Ko parāda celtņa bremžu funkcionālā pārbaude pirms lietošanas?","Jūs vēlaties droši noturēt kravu.","Vai bremze apstājas un notur kustību, kā paredzēts.","Tikai vai salona apgaismojums darbojas.","Vai āķis var automātiski noturēt kravu.","Pirms lietošanas ir jāpārbauda ar drošību saistītās funkcijas saskaņā ar specifikācijām."],"k-schraegzug":["Vai ar celtni var vilkt sānu kravu leņķī?","Āķis neatrodas vertikāli virs kravas.","Jā, ja celtnim vēl ir slodzes rezerve.","Nē, kravas nedrīkst vilkt, izmantojot neatļautas diagonālās vilkšanas.","Jā, ja stropes ir īpaši īsas.","Vilkšana pa diagonāli var izraisīt nekontrolētas kustības un papildu slodzi celtnim un stropēm."],"k-verhakt":["Uz apakšbūves karājas slodze. Kas ir pareizi?","Paceļot ir jūtama pretestība.","Jūs turpiniet celt, līdz tas atdalās.","Jūs saraustīti pārvietojat kravu uz sāniem.","Jūs apstājaties un droši noņemat stiprinājumu vai aizsprostojumu.","Iestrēgušo kravu nedrīkst atraut ar spēku, jo var rasties nepieņemami spēki."],"k-anzuheben":["Ko jūs pārbaudāt, pirmo reizi īslaicīgi paceļot piekārtu kravu?","Krava paceļas dažus centimetrus no zemes.","Vai tas karājas līdzsvarā un pietura ir droša.","Vai cilvēks var pakļaut sevi tieši zem slodzes.","Vai celtnis kļūst stabilāks, ātri pagriežoties.","Īsi kontrolēta celšana tiek izmantota, lai pārbaudītu stiprinājumu, līdzsvaru un drošu kravas uzvedību."],"k-lastweg":["Kur jābūt celtņa kravas transportēšanas maršrutam?","Vairākas darba vietas atrodas zem iespējamās slodzes ceļa.","Ja iespējams, virs aizņemtām darbstacijām.","Pa ieplānotu, skaidru ceļu bez apdraudētiem cilvēkiem.","Vienmēr pa diagonāli cauri noslogotākajai zonai.","Kravu ceļi jāorganizē tā, lai cilvēkus neapdraudētu piekārtas kravas."],"k-signalverlust":["Pārtrūkst radio savienojums ar maršalu. ko tu dari?","Jūs nevarat redzēt pašu slodzes ceļu.","Jūs turpiniet kustību lēnām.","Jūs eksperimentāli šūpojaties iepriekšējā virzienā.","Jūs pārtraucat kustību, līdz rodas skaidra, droša izpratne.","Ja trūkst komunikācijas, mulsinoša slodzes kustība var neturpināties."],"k-haken":["Drošības āķis neaizveras droši. Kas ir pareizi?","Pārbaudes laikā tiek pamanīts bojāts slēgs.","Pirms turpmākas lietošanas kļūda ir profesionāli jānovērš.","Jūs cieši piesienat aizdari ar kabeļa saiti.","Jūs izmantojat āķi tikai vieglām slodzēm.","Bojātas nostiprināšanas ierīces uz kravas āķiem var izraisīt stropu atvienošanu, un tās ir jānovērš."],"k-zugrichtung":["Kas ir svarīgi kravas vertikālajam atbalstam?","Krava ir jāpaceļ no mašīnas.","Celtņa āķim jābūt izlīdzinātam virs kravas smaguma centra.","Āķis jānovieto pēc iespējas uz sāniem.","Pirms pacelšanas krava ir jāstumj.","Spēka efekts, kas ir maksimāli vertikāls virs slodzes centra, novērš nepieļaujamus sānu spēkus un nekontrolētu šūpošanos."],"k-wartung":["Uz celtņa tiek pamanīts neparasts slīpēšanas troksnis. Kā jūs to darāt?","Troksnis rodas pacelšanas laikā.","Nosedziet troksni ar lielāku ātrumu.","Droši pārtrauciet darbību, ziņojiet par defektiem un lieciet tos novērst.","Turpiniet strādāt bez brīdinājuma līdz pārtraukumam.","Ievērojamas izmaiņas var norādīt uz drošību nozīmīgiem bojājumiem, un tādēļ ir nepieciešama pārbaude."],"k-absetzen":["Kas jāgarantē, nolaižot celtņa kravu?","Uz virsmas ir novietota smaga slodze.","Krava var atrasties nenostiprināta uz slīpas virsmas.","Stropes tiek noņemtas, kamēr tās vēl peld.","Krava ir stabila un nodrošināta pret apgāšanos vai ripošanu.","Kravu drīkst atbrīvot no stropes tikai pēc tam, kad tā ir droši novietota un nodrošināta stabilitāte."],"l-schwerpunkt":["Kāpēc pirms sitiena ir jāzina smaguma centrs?","Ir jātransportē asimetriskas formas mašīna.","Lai celšanas laikā slodze saglabātos pēc iespējas līdzsvarotāka.","Lai stropes varētu izvēlēties tik garas, cik vēlas.","Lai pieļaujamā kravnesība nespēlē lomu.","Smaguma centra novietojums ietekmē slodzes sadalījumu un drošu līdzsvaru pacelšanas laikā."],"l-etikett":["Pacelšanas siksnai nav nolasāmas kravnesības uzlīmes. Kas ir pareizi?","Marķējums ir kļuvis neatpazīstams.","Novērtējiet kravnesību, pamatojoties uz krāsu.","Neizmantojiet pacelšanas siksnu, kamēr tās piemērotība nav skaidri pierādīta.","Nelielām slodzēm izmantojiet jostu tikai vienu reizi.","Stropēm ir nepieciešams atbilstošs marķējums; Neizskaidrojama kravnesība izslēdz drošu izvēli."],"l-kantenschutz":["Virs asas tērauda malas atrodas tekstila lente. Kas ir nepieciešams?","Kravai ir asas malas.","Pievelciet joslu pēc iespējas ciešāk bez aizsardzības.","Veiciet sitienu ātrāk.","Izmantojiet piemērotu malu aizsargu vai citu piemērotu stropes aprīkojumu.","Asas malas var sabojāt vai sagriezt tekstila stropes; nepieciešama atbilstoša aizsardzība."],"l-spreizwinkel":["Kā lielāks slīpuma leņķis ietekmē slodzi uz stropēm?","Krava tiek pacelta, izmantojot divas slīpas virves.","Mazāk labvēlīgos leņķos spēki dzīslās var palielināties.","Stiepes spēki pazūd.","Leņķim nav ietekmes uz spriegumu.","Ar mazāk labvēlīgu pieturas leņķi spēki uz vienu šķipsnu var palielināties; Jāievēro kravnesības tabulas."],"l-knoten":["Vai stropes virvi var saīsināt pēc vēlēšanās, izmantojot mezglu?","Virve ir pārāk gara plānotajai slodzei.","Jā, ciešs mezgls uzlabo kravnesību.","Nē, izmantojiet tikai apstiprinātas saīsināšanas un noenkurošanas metodes.","Jā, ja mezgls ir nostiprināts ar lenti.","Nepieļaujami mezgli vājina stropes un maina to pieļaujamo kravnesību."],"l-zeichen":["Kas attiecas uz saziņu ar celtņa operatoru?","Slodzes ceļš ir daļēji aizsegts.","Vairāki cilvēki vienlaikus dod dažādus signālus.","Tiek izmantoti skaidri, iepriekš saskaņoti signāli.","Saziņa ar radio celtņiem nekad nav nepieciešama.","Skaidras zīmes un skaidri pienākumi novērš bīstamas nepareizas kustības."],"l-sichtpruefung":["Kad jāpārbauda, ​​vai stropēm nav redzamu defektu?","Jūs vēlaties izmantot stropes ķēdi.","Pirms lietošanas pievērsiet uzmanību jebkādiem ārēji redzamiem bojājumiem.","Tikai tad, ja nelaime jau ir notikusi.","Tikai vienu reizi, pirmo reizi iegādājoties.","Pirms katras lietošanas ir jānovērtē drošs darba stāvoklis; Redzams bojājums izslēdz drošu lietošanu."],"l-drehung":["Pacelta krava sāk nekontrolējami griezties. ko tu dari?","Krava pārvietojas kravas ceļā.","Jūs ievietojat roku starp kravu un sienu.","Tu noliec sevi zem nastas un turies pie tās.","Jūs ievērojat distanci un ļaujat kustībai kontrolēti apstāties.","Nekontrolētas kravas kustības rada saspiešanas un trieciena draudus; Cilvēkiem ir jāatstāj bīstamā zona."],"l-ablegen":["Kad var noņemt stropes no kravas?","Slodze tiek novietota uz estakādēm.","Ja krava ir stabila un nodrošināta pret apgāšanos vai ripošanu.","Tiklīdz tas pirmo reizi pieskaras zemei, neatkarīgi no tā stāvokļa.","Joprojām turot kursoru, lai ietaupītu laiku.","Stropes drīkst noņemt tikai pēc tam, kad tās ir droši un stabili novietotas."],"l-ketten":["Ķēdes stropei ir stipri saliekts posms. ko tu dari?","Bojājums ir redzams pat pirms pacelšanas.","Aptiniet bojāto vietu ar stiepli.","Noņemiet ķēdi no lietošanas un pārbaudiet to profesionāli.","Paceliet slodzi tikai uz pusi augstāk.","Deformēti ķēdes posmi ir redzami bojājumi, kas var kavēt drošu lietošanu."],"b-einweiser":["Kas ir svarīgi, ja redzamība no ekskavatora ir ierobežota?","Ēkas daļa aizsedz braukšanas zonu.","Atbilstoši vizuāli pasākumi vai instrukcija un skaidra komunikācija.","Vienkārši skatīties kapuci.","Brauciet pa grozāmo zonu, neskatoties uz to, ka esat neredzams.","Ja redzamība ir ierobežota, ir jānovērš apdraudējumi ar papildu organizatoriskiem un tehniskiem pasākumiem."],"b-aushub":["Kur var uzglabāt izrakto materiālu pie būvbedres?","Bedres malu nedrīkst pakļaut papildu riskam.","Salieciet kaudzes tieši uz malas, lai piebraucamie ceļi paliktu brīvi.","Uzglabāt pietiekami drošā attālumā un atbilstoši būvlaukuma specifikācijām.","Novietojiet uz vaļīga atbalsta bez papildu pārbaudes.","Izraktais materiāls var apdraudēt uzbērumus un nostiprinājumus papildu slodžu dēļ; Jāievēro drošības attālumi."],"b-personen":["Vai cilvēkiem ir atļauts uzturēties šūpoļu zonā, kamēr ekskavators kustas?","Panoramēšanas laikā cilvēks vēlas izmērīt.","Jā, ja vien viņa valkā aizsargķiveri.","Jā, ja ekskavators šūpojas lēni.","Nē, bīstamajai zonai pirms kustības ir jābūt brīvai.","Pagrieziena zonā pastāv nopietnu saspiešanas un trieciena traumu risks; vietai jābūt brīvai."],"b-ladung":["Kā jūs droši transportējat materiālus ar riteņu iekrāvēju?","Ar piepildītu lāpstu jābrauc pāri pagalmam.","Ar piemērotu zemu transportēšanas pozīciju un brīvu ceļu.","Ar paceltu lāpstu labākai redzamībai.","Ar atvērtām durvīm un spēcīgu stūres leņķi.","Piemērota transportēšanas pozīcija samazina apgāšanās risku un uzlabo braukšanas stabilitāti."],"b-anbaupruefung":["Ko jūs pārbaudāt pēc pielikuma pievienošanas?","Pielika jaunu lāpstu.","Tikai krāsojuma tīrība.","Droša bloķēšana un darbība saskaņā ar lietošanas instrukciju.","Tikai vai ierīce izskatās vienādi no ārpuses.","Nepareizas ātro savienotāju bloķēšanas var izraisīt nejaušu papildierīču atlaišanu."],"b-einstieg":["Kā droši iekļūt ekskavatora kabīnē?","Pēc lietus pakāpieni ir netīri.","Uzkāpiet kabīnē caur izlici.","Uzkāp uz kāpuriem vienā lēcienā.","Izmantojiet norādītos pakāpienus un rokturus un notīriet netīrās pakāpienus.","Piemēroti kāpumi un droši turēšanas punkti samazina paslīdēšanas un kritiena risku."],"b-graben":["Tranšejas sienā ir redzamas plaisas un tā drūp. Kas ir pareizi?","Tu strādā turpat pie grāvja.","Pārtrauciet darbu un lieciet atbildīgajiem nodrošināt rakšanas bedri.","Vienkārši brauciet tuvāk malai, lai aizvērtu grāvi.","Padziļiniet tranšeju tālāk bez aizsardzības.","Plaisas un zemes kustības var liecināt par nestabilitāti un prasīt papildu drošības novērtējumu."],"b-betanken":["Kam pievērst uzmanību, uzpildot degvielu zemes pārvietošanas mašīnai?","Tvertne ir gandrīz tukša.","Nostipriniet dzinēju un aizdedzes avotus saskaņā ar ražotāja norādījumiem un izvairieties no izšļakstīšanās.","Vienmēr uzpildiet benzīnu vai dīzeļdegvielu salonā.","Smēķējiet degvielas uzpildes laikā, kad nav vēja.","Ugunsgrēka un vides apdraudējuma gadījumā, strādājot ar degvielu, nepieciešami atbilstoši aizsardzības pasākumi."],"b-laufwerk":["Kāpēc regulāri jāpārbauda kāpurķēdes un šasijas?","Braucot pamanāt neparastas vibrācijas.","Lai mašīna varētu kustēties ātrāk.","Tā kā bojājumi var ietekmēt drošu vadību un stabilitāti.","Jo darbs vienmēr ir atļauts bez vizuālas pārbaudes.","Piedziņas bojājumi var ietekmēt manevrētspēju, stabilitāti un drošu darbību."],"b-einweisen":["Kas nepieciešams, strādājot publiskās gājēju satiksmes tuvumā?","Ekskavators strādā tieši uz ietves malas.","Gājējiem pašiem jāpārvietojas pa šūpoļu laukumu.","Vienkārši uzlīmējiet zīmi uz lāpstas.","Efektīvi norobežojiet bīstamo zonu un droši virziet satiksmi.","Trešās personas nedrīkst iekļūt zemes pārvietošanas mašīnu bīstamajā zonā; Nepieciešamas atbilstošas ​​barjeras un satiksmes maršruti."],"g2-fahrweg":["Priekšā uz ceļa ir izlijis šķidrums. Kā jūs to darāt?","Iekrāvējs brauktu tieši pāri slidenai zonai.","Pārtrauciet braukšanu un nodrošiniet vai noņemiet bīstamo vietu.","Brauciet pāri vietai pēc iespējas ātrāk ar paceltu dakšu.","Ceru uz sausākām riepām un turpināt braukt bez izmaiņām.","Piesārņotie ceļi apdraud stabilitāti, un pirms braukšanas pa tiem ir atbilstoši jānostiprina."],"g2-sichtladung":["Augsta palete bloķē skatu uz priekšu. Kas ir pareizi?","Jums jābrauc uz noliktavas laukumu, un jūs nevarat redzēt maršrutu.","Paceliet paleti uz augšu, līdz redzat zem tās.","Brauciet tikai, izmantojot piemērotas, drošas metodes, piemēram, braucot atpakaļgaitā ar skaidru skatu.","Jūs joprojām varat braukt pa ceļu bez norāžu zīmes vai skaidra skata.","Braukšanas virzienam un redzamībai jārada iespēja droši novērot satiksmes maršrutu; Kravas nedrīkst aizstāt vizuālo pārbaudi."],"g2-fussgaengerstop":["Gājējs apstājas tieši pie iekrāvēja. ko tu dari?","Persona atrodas iespējamā braukšanas un pagrieziena diapazonā.","Apdzen gājēju, īsi paātrinot.","Brauciet garām cilvēkam ar paceltu kravu.","Apstājieties un turpiniet braukt tikai drošā attālumā.","Cilvēkiem jāatrodas ārpus bīstamās zonas; Ja nepieciešams, brauciens jāpārtrauc."],"g2-hubmast":["Jūs pamanāt bojātu hidraulisko līniju uz pacelšanas masta. Kas attiecas?","No agregāta redzami izplūst hidrauliskā eļļa.","Izņemiet iekrāvēju no ekspluatācijas un ziņojiet par bojājumiem.","Pacelšanas laikā pārbaudiet noplūdi ar roku.","Paceliet mazākas kravas tikai līdz maiņas beigām.","Hidrauliskie bojājumi var izraisīt nekontrolētas kustības; droša lietošana nav garantēta līdz pārbaudei."],"g2-lagerregal":["Jūs vēlaties glabāt paleti plauktā. Ko jūs vispirms pārbaudāt?","Plauktu līmenis ir augsts, un kravnesība ir jāsaglabā.","Pēc iespējas ātrāk uzspiediet paleti uz plaukta.","Pārbaudiet plauktu nodalījuma, kravas svara un brīvās uzglabāšanas vietas piemērotību.","Aprēķiniet kopējo svaru, pamatojoties tikai uz kastu skaitu.","Plauktiem un kravas pārvadāšanas iekārtām jāatbilst kravas un uzglabāšanas situācijai."],"g2-batterieschaden":["Iekrāvēja akumulators ir bojāts ārēji. Kas ir pareizi?","Pirms iekraušanas tiek pamanītas plaisas vai neparasts šķidrums.","Pārklājiet bojājumus ar līmlenti un nekavējoties ievietojiet tos.","Ļaujiet citai personai uzlādēt akumulatoru, to nepārbaudot.","Neuzlādējiet un neizmantojiet un informējiet atbildīgos speciālistus.","Bojāti akumulatori rada elektrisku un ķīmisku apdraudējumu, un tiem ir nepieciešams profesionāls novērtējums."],"g2-fahrerkabine":["Kas attiecas uz vaļīgiem priekšmetiem vadītāja zonā?","Instrumenti atrodas uz grīdas blakus vadības pedāļiem.","Noņemiet priekšmetus un turiet darbības zonu brīvu.","Braukšanas laikā instrumentu turiet tikai ar vienu kāju.","Paslēpiet vaļīgās daļas zem vadītāja sēdekļa.","Brīvi priekšmeti var bloķēt pedāļus un traucēt transportlīdzekļa drošu darbību."],"g2-uebergabe":["Jūs pārņemat autoiekrāvēju pēc maiņas maiņas. Ko tas ietver?","Kolēģis pēdējo reizi izmantoja transportlīdzekli.","Pieņemsim, ka kolēģis ir pārņēmis visas pārbaudes.","Veikt nepieciešamo pārbaudi un interesēties par zināmajiem defektiem.","Sāciet braucienu, neskatoties uz mašīnu.","Personai, kas pārņem, pirms lietošanas jāpārliecinās, ka tas ir drošā stāvoklī."],"g2-transportsicherung":["Uz paletes ir vaļīgs augsts priekšmets. Kā tu rīkojies?","Bremzējot krava var sasvērties uz priekšu.","Dakšu nēsājiet īpaši augstu, lai krava būtu stabila.","Vienkārši ņemiet līkumus lēnām, ejiet taisni ātrāk.","Novietojiet kravu stabili un nodrošiniet to pret apgāšanos vai krišanu.","Brīvās kravas pirms transportēšanas ir jāstabilizē, lai bremzēšanas un braukšanas kustības neizraisītu to krišanu."],"g2-arbeitsende":["Kas ir svarīgi bez uzraudzības atstātam iekrāvējam?","Jūs beidzat savu maiņu un atstājat zonu.","Novietojiet automašīnu droši un nodrošiniet to pret ripošanu un neatļautu izmantošanu.","Atstājiet atslēgu, lai kolēģi var atrast mašīnu.","Atstājiet dakšiņu acu līmenī, lai tā būtu redzama.","Droša stāvvieta ietver pazeminātu kravas pārvietošanu un aizsardzību pret kustību un nesankcionētu nodošanu ekspluatācijā."],"g2-bremsweg":["Kāpēc īpaša uzmanība jāpievērš bremzēšanas ceļam pie slodzes?","Iekrāvējs pārvadā smagās kravas pa noliktavas eju.","Ar lielu slodzi vienmēr bremzējiet vēlāk nekā bez kravas.","Pielāgojiet ātrumu redzamības, zemes un slodzes apstākļiem.","Bremzējot, strauji paceliet kravu, lai labāk palēninātu.","Masa un ceļa stāvoklis ietekmē bremzēšanas ceļu; pielāgots ātrums ir galvenais."],"g2-rampe":["Ko jūs pārbaudāt, pirms kāpjat pa stāvu rampu?","Maršruts var būt pārāk stāvs transportlīdzeklim.","Brauciet pa rampu ar maksimālo ātrumu neatkarīgi no slīpuma.","Brauciet pāri rampas malai ar paceltu kravu.","Pārbaudiet pieļaujamo slīpumu un drošo darbības režīmu no transportlīdzekļa specifikācijām.","Drīkst izmantot tikai rampas paredzētajās ekspluatācijas robežās; Lietošanas instrukcija un slodzes kontrole ir izšķiroša."],"g2-zinke":["Palete ir platāka par dakšu attālumu. Kas jāņem vērā?","Jūs plānojat uzņemties neparasti lielu slodzi.","Pielāgojiet dakšas attālumu un stiprinājuma punktus atbilstoši slodzei.","Ja slodze ir pārāk plata, izmantojiet tikai vienu zaru.","Paceliet kravu leņķī, līdz tā sasniedz pareizo pozīciju.","Vienmērīga un piemērota slodzes absorbcija samazina slīdēšanu un apgāšanos."],"g2-betriebsanweisung":["Kāda loma ir operatīvajam satiksmes regulējumam?","Noliktavā ir iezīmētas vienvirziena un gājēju zonas.","Uz iekrāvējiem attiecas tikai koplietošanas ceļu noteikumi.","Ievērojiet norādītos maršrutus un satiksmes noteikumus.","Ignorējiet marķējumus, kad transportlīdzeklis ir iekrauts.","Uzņēmuma maršruti un drošības noteikumi aizsargā autoiekrāvēju satiksmi un cilvēkus, kas iet kājām."],"g2-nothalt":["Stūre braukšanas laikā reaģē neparasti. Kas ir pareizi?","Transportlīdzekli vairs nevar vadīt kā parasti.","Brauciet ar lielāku ātrumu, lai stūre būtu atsaucīgāka.","Kompensējiet kļūdu ar īpaši lielām stūres novirzēm.","Apstājieties drošā vietā un pārbaudiet transportlīdzekli.","Bojāta stūrēšana apdraud drošu vadību; mašīnu nedrīkst turpināt nekontrolēti darbināt."],"g2-anschlagkette":["Jūs vēlaties pārvietot brīvi piekārtu kravu ar iekrāvēju. Kas attiecas?","Zem dakšām uz āķa jākaras kravai.","Tikai ar apstiprinātu ierīci un piemērotu kravas pārvadāšanas aprīkojumu.","Derēs jebkura ķēde, ja slodze nav smaga.","Saspiediet ķēdi tieši starp abām dakšām.","Brīvi piekārtas kravas maina stabilitāti; Nepieciešami ražotāja apstiprinājumi un piemērotas iekārtas."],"g2-rollenlast":["Cilindriska detaļa nenostiprināta atrodas uz paletes. ko tu dari?","Krava transportēšanas laikā var ripot.","Pieejiet pie paletes īpaši saraustīti.","Pirms paletes pacelšanas nostipriniet sastāvdaļu pret ripošanu.","Novietojiet zarus pietiekami augstu, lai sastāvdaļa nebūtu redzama.","Apaļām vai ritošām slodzēm nepieciešama uzticama aizsardzība pret stāvokļa izmaiņām."],"g2-pruefplakette":["Kā zināt, vai iekrāvēju var izmantot?","Mašīnai ir pielīmēta pārbaudes uzlīme.","Jebkura uzlīme vienmēr aizstāj ikdienas vizuālo pārbaudi.","Klīrensa trūkumu var aizstāt ar uzmanīgu braukšanu.","Papildus transportlīdzekļa pārbaudei ir jāņem vērā derīgs pārbaudes statuss un ekspluatācijas apstiprinājums.","Atkārtotās pārbaudes un ikdienas darbības kontroles veic dažādas drošības funkcijas."],"g2-licht":["Noliktavā pēkšņi nodzisa apgaismojums. Kas ir pareizi?","Jūs vairs nevarat droši redzēt šķēršļus ceļā.","Pārtrauciet braukšanu, līdz tiek garantēta droša redzamība.","Palieliniet braukšanas ātrumu, lai atstātu tumšo zonu.","Turpiniet braukt ar paceltām dakšām bez vizuālas pārbaudes.","Maršrutu, kuru nevar droši nepamanīt, nedrīkst braukt bez efektīviem drošības pasākumiem."],"g2-ueberhang":["Krava sniedzas tālu aiz dakšas malas. Ko jūs pārbaudāt?","Jūs vēlaties transportēt paleti caur šauriem vārtiem.","Kompensējiet sānu projekciju ar ātru līkni.","Pirms braukšanas novērtējiet klīrensu, stabilitāti un pieļaujamo kravnesību.","Brauciet ar maksimālo ātrumu neatkarīgi no tās formas.","Pārkares palielina sadursmes risku un var mainīt stabilitāti un nepieciešamo satiksmes telpu."],"g2-wartungsbereich":["Tehniskās apkopes zonas priekšā ir barjeras. Kā tu uzvedies?","Jūsu parastais maršruts uz laiku ir slēgts.","Īsi pārvietojiet barjeras un brauciet cauri nepamanīti.","Brauciet tieši cauri darba zonai zem slodzes.","Ievērojiet slēgšanu un izvēlieties apstiprinātu alternatīvu maršrutu.","Iekļūt norobežotajās zonās vai braukt pa tām bez atļaujas nedrīkst."],"g2-bremsprobe":["Kad ir jēga veikt darba bremžu funkcionālo pārbaudi?","Pirms darba sagatavojat iekrāvēju.","Kā daļa no nepieciešamās pārbaudes pirms lietošanas.","Veikt tikai pēc smagas avārijas.","Tikai tad, ja kravas automašīna jau ir sasniegusi lielu ātrumu.","Pirms lietošanas tiek pārbaudīta ar drošību saistīto iekārtu funkcionalitāte."],"g2-fahrzeuganhaenger":["Jūs vēlaties vilkt piekabi ar iekrāvēju. Kas ir nepieciešams?","Uzņēmums plāno transportu ar pievienoto kravu.","Piesiet katru piekabi pie dakšas bez pārbaudes.","Ievērojiet ražotāja apstiprinājumu, piemērotu savienojumu un pieļaujamo stiepes slodzi.","Vienkārši palieliniet riepu spiedienu un brauciet.","Vilciena darbība ir iespējama tikai saskaņā ar tehniskajām specifikācijām un ar piemērotu savienojumu."],"g2-rueckfahrt":["Kas ir svarīgi, braucot atpakaļgaitā ar iekrāvēju?","Noliktavas ejā ir mulsinoša zona.","Vienmēr skatieties tikai atpakaļskata spogulī neatkarīgi no apkārtnes.","Brauciet bez redzamības, kamēr vienreiz ir nospiests skaņas signāls.","Droši ievērojiet maršrutu un cilvēku zonu un, ja nepieciešams, ļaujiet viņiem instruēt.","Lai pārvietotos atpakaļgaitā, ir nepieciešams skaidrs skats vai efektīvi papildu drošības pasākumi."],"g2-lastentnahme":["Jūs izņemat paleti no augsta plaukta. Kas ir pareizi?","Palete var nebūt centrēta.","Droši paņemiet kravu un nostabilizējiet to pirms nolaišanas.","Ļaujiet paletei šūpoties uz sāniem, kamēr to izvelkat.","Pārbaudiet zem paceltās paletes, lai redzētu, vai tā nav bojāta.","Kontrolēta pacelšana un nolaišana novērš kravu krišanu un bīstamas kustības."],"h2-absenkweg":["Kāpēc laukumam zem pacēlāju platformas ir jāpaliek brīvai?","Grozs ir nolaists un zem tā novietoti materiāli.","Nospiediet materiālus ar grozu.","Pievērsiet uzmanību tikai operatora pēdas zonai.","Nolaižot, izvairieties no saspiešanas un sadursmes riska.","Nolaišanas zonā nedrīkst atrasties cilvēki vai šķēršļi, kas varētu iesprūst."],"h2-transporthoehe":["Kā pārvietot mobilo skatuvi pa zemu eju?","Klīrenss ir zemāks par pagarināto izlici.","Novietojiet platformu piemērotā transportēšanas pozīcijā saskaņā ar lietošanas instrukciju.","Atstājiet izlici izstieptu un pārvietojieties zem griestiem.","Piespiediet grozu pret durvju rāmja malu.","Braukšanas kustībām kopējam augstumam un transportēšanas pozīcijai jāatbilst ražotāja specifikācijām un pārejai."],"h2-bodenoeffnung":["Grīdā blakus skatuvei ir nenodrošināta atvere. Kā jūs reaģējat?","Braukšanas vai atbalsta punkts atrodas netālu no atveres.","Novietojiet balstu tieši uz atveres malas.","Mainiet uzstādīšanas vietu vai profesionāli pārbaudiet kravnesību un stiprinājumus.","Bīstamo vietu nosedziet tikai ar kartona kasti.","Atveres un malu laukumi var sabojāt atbalsta slodzes ietekmē, un tie ir efektīvi jāņem vērā."],"h2-rettungsperson":["Kāpēc otrai personai ir jāzina glābšanas procedūra?","Operators augšpusē var kļūt rīcībnespējīgs.","Lai darbs grozā kopumā varētu notikt bez drošības.","Lai estrāde varētu darboties ātrāk nekā atļauts.","Lai ārkārtas situācijā varētu uzsākt drošu glābšanu.","Glābšanas koncepcijā ir jāņem vērā palīdzība uz zemes avārijas vai avārijas gadījumā."],"h2-werkzeugabwurf":["Kas attiecas uz instrumentiem lielā augstumā?","Vaļīgs instruments var pārkrist pāri groza malai.","Nostipriniet instrumentus tā, lai tie nevienu neapdraudētu vai nenokristu.","Vienkārši novietojiet instrumentus uz margām, lai samazinātu slodzi.","Ja nepieciešams, izmetiet instrumentus no groza.","Krītoši priekšmeti apdraud zemāk esošos cilvēkus; Materiāls ir jāuzglabā droši."],"h2-trittstufe":["Kā papildu stāvvieta grozā jākalpo kastei. Kas ir pareizi?","Pretējā gadījumā jūs tik tikko sasniegsit darba vietu.","Novietojiet kasti uz margām un uzkāpiet uz tās.","Nekāpiet uz improvizētiem paaugstinājumiem; Izmantojiet piemērotu darba aprīkojumu.","Apzināti ievietojiet grozu virs atļautā augstuma.","Improvizēti paaugstinājumi pasliktina paredzēto aizsardzību pret kritienu un nav atļauti."],"h2-lastverteilen":["Kam pievērst uzmanību, ja darba grozā ir vairāki cilvēki?","Grozā strādā divi cilvēki ar smagiem instrumentiem.","Novērtējiet slodzi, pamatojoties tikai uz instrumenta izmēru.","Glabājiet smagos instrumentus tieši uz aizsargmargām.","Nepārsniedziet pieļaujamo groza slodzi, ieskaitot cilvēkus un instrumentus.","Atļautā kravnesība ietver visus grozā esošos cilvēkus, materiālus un instrumentus."],"h2-abstuetzplatte":["Kad tiek apsvērti papildu starplikas balstiem?","Uzstādīšanas grīda var izturēt tikai ierobežotu slodzi.","Ja tas ir nepieciešams drošai slodzes sadalei atbilstoši specifikācijām.","Lai balstus novietotu pēc iespējas tuvāk būvbedres malai.","Lai izmantotu lielāku diapazonu bez ražotāja informācijas.","Lai nodrošinātu drošus atbalsta spēkus, ir nepieciešamas pietiekamas saskares zonas."],"h2-baugrube":["Estrādei jāatrodas tieši būvbedres malā. Ko jūs pārbaudāt?","Rakšanas bedres dēļ zemes dzīle varētu padoties sāniski.","Izstiepiet balstus rakšanas bedrē.","Nodrošiniet pietiekamu drošības attālumu un pamatnes nestspēju.","Tikai kompensējiet risku, lēnām paceļot grozu.","Rakšanas bedres var ietekmēt stabilitāti slīpuma un grunts bojājumu dēļ."],"h2-witterung":["Lietošanas laikā iedarbojas apledojums. Kā tu rīkojies?","Vadības virsmas un darba zona kļūst gluda.","Paceliet skatuvi, lai izvairītos no sniega un ledus.","Ignorējiet brīdinājumus, kamēr platforma ir apgaismota.","Pārtrauciet darbu un atkārtoti novērtējiet ekspluatācijas apstākļus saskaņā ar lietošanas instrukciju.","Laikapstākļu izmaiņas var mainīt atbildību, darbību un drošus lietošanas ierobežojumus."],"h2-aufbaukontakt":["Tērauda konstrukcija ierobežo groza ceļu. Kas ir svarīgi?","Paceļot pastāv saspiešanas risks starp grozu un turētāju.","Plānojiet kustības tā, lai jūsu ķermenis un grozs netiktu iesprostoti.","Padariet braucienu ātrāku, lai grozs ātrāk paietu garām.","Pabīdiet konstrukciju ar grozu uz sāniem.","Saspiešanas punkti starp platformu un vidi prasa rūpīgu novērošanu un kontrolētu kustību."],"h2-sicherheitsabstand":["Kad ir jānožogo estrādes bīstamā zona?","Zem objekta iet sabiedriskā transporta maršruts.","Tikai tad, ja kāds priekšmets jau ir nokritis.","Ja trešās personas var apdraudēt kustība vai krītoši priekšmeti.","Nekad, jo darba grozs pamatā novērš visas briesmas.","Teritorija zem un blakus estrādei ir jāaizsargā pret paredzamiem apdraudējumiem."],"h2-korbtor":["Kas attiecas uz darba būra ieejas durvīm?","Jūs jau esat darba augstumā.","Atstājiet durvis vaļā, lai varētu ātrāk izkļūt.","Piesieniet durvis pastāvīgi atvērtas ar virvi.","Turiet durvis aizvērtas atbilstoši nodrošinātajam bloķēšanas mehānismam.","Nodrošinātās slēdzenes ir daļa no aizsardzības pasākumiem pret izkrišanu no darba būra."],"h2-energieleitung":["Ko darīt, ja gaisvadu līnija nav droši atslēgta?","Jūs strādājat ar pacēlāju darba platformu viņu tuvumā.","Nodrošiniet noteiktos drošības attālumus un nepieciešamos aizsardzības pasākumus.","Pārvietojiet grozu tieši līnijas priekšā, kamēr tas netiek aizskarts.","Uzticieties plastmasas riepām un strādājiet bez atstarpēm.","Elektriskie uzliesmojumi ir iespējami arī bez tieša kontakta; Nepieciešami drošības attālumi."],"h2-schwanken":["Darba grozs sāk neparasti spēcīgi šūpoties. Kas ir pareizi?","Kustība vairs netiek kontrolēta.","Nekontrolējami pielāgojieties ar ātrām pret kustībām.","Apturiet kustību un pārbaudiet cēloni vai darbības apstākļus.","Pievienojiet grozam papildu cilvēkus, lai padarītu to smagāku.","Neparastas vibrācijas var norādīt uz nepiemērotiem darbības apstākļiem vai darbības traucējumiem."],"h2-ladegeraet":["Bojāts elektriski darbināmas stadijas uzlādes kabelis. ko tu dari?","Savienojot, ir redzama bojāta izolācija.","Pieskarieties bojājumiem ar mitriem cimdiem.","Iespiediet kontaktdakšu kontaktligzdā pēc iespējas ciešāk.","Nesāciet uzlādes procesu un profesionāli pārbaudiet kabeli.","Bojāta elektroinstalācija rada elektriskās strāvas trieciena un aizdegšanās risku."],"h2-gelaenderanbau":["Vai varat pats noņemt margas, lai piebrauktu tuvāk?","Komponents neļauj cilvēkiem tuvoties darba vietai.","Nepārveidojiet vai nenoņemiet aizsargierīces saviem spēkiem.","Pēc pacelšanas atskrūvējiet margas un uzstādiet tās vēlāk.","Turpiniet strādāt bez margām, kamēr kāds stāv blakus.","Konstrukciju aizsargierīces nedrīkst mainīt bez pieļaujamām specifikācijām un drošiem nomaiņas pasākumiem."],"h2-lastkran":["Vai platformu var izmantot kā celtni kravas pacelšanai?","Materiāls jātransportē brīvi pakārts blakus darba grozam.","Ikreiz, kad svars ir mazāks par jūsu ķermeņa svaru.","Tikai tad, ja ražotājs un aprīkojums ir skaidri atļāvis šo īpašo izmantošanu.","Vienkārši piestipriniet āķi pie margām un paceliet materiālu.","Gaisa darba platformas nav automātiski paredzētas darbam ar celtni vai papildu piekārtām kravām."],"h2-arbeitsvorbereitung":["Kas notiek, gatavojoties jaunai vietai?","Jūs vēl nezināt būvlaukumu.","Vienkārši novērtējiet attālumu līdz tuvākajai autostāvvietai.","Neatkarīgi no apkārtnes nekavējoties pilnībā pagariniet to.","Novērtējiet apdraudējumus, augsni, satiksmes ceļus, glābšanas un aprīkojuma piemērotību.","Ar atrašanās vietu saistīts riska novērtējums ir drošu ekspluatācijas apstākļu priekšnoteikums."],"h2-kabelschlaufe":["Strāvas kabelis atrodas pāri skatuves ceļam. Kas ir pareizi?","Kustības laikā kabelis var iesprūst.","Atbrīvojiet ceļu un pasargājiet elektrības kabeļus no bojājumiem.","Izmantojiet kabeli ar riteņiem kā ceļa slieksni.","Paceliet grozu, nepārbaudot grīdas laukumu.","Pārbraukti vai saspiesti kabeļi var izraisīt elektriskus un mehāniskus apdraudējumus."],"h2-leitungsnaehe":["Kurš precizē elektriskās sistēmas aizsardzības pasākumus?","Platformai jādarbojas tuvu esošam aprīkojumam.","Cilvēks grozā izlemj tikai pēc acs.","Iesaistīt atbildīgās iestādes un īstenot saskaņotus aizsardzības pasākumus.","Distance tiks noteikta tikai pēc darba uzsākšanas.","Strādājot elektrisko sistēmu tuvumā, nepieciešami plānoti un saskaņoti aizsardzības pasākumi."],"h2-funkkommunikation":["Kāpēc signāliem starp grīdu un grozu ir jābūt skaidriem?","Cilvēks uz zemes palīdz manevrēt.","Lai vairāki cilvēki vienlaikus varētu dot pretrunīgus norādījumus.","Lai avārijas nolaišanu varētu izmēģināt bez instrukcijām.","Lai kustības tiktu veiktas tikai pēc skaidras komunikācijas.","Skaidra komunikācija samazina nepareizas kustības un sadursmes manevrēšanas laikā."],"h2-neuebedienung":["Jūs pārslēdzaties uz cita veida skatuvi. Kas ir nepieciešams?","Darbības funkcijas ievērojami atšķiras.","Ierīcei specifiska instrukcija pirms neatkarīgas lietošanas.","Vienkārši izlasot uzņēmuma logotipu uz ierīces.","Izmēģinājuma brauciens ar jau pagarinātu grozu bez instrukcijām.","Kvalifikācija pati par sevi neaizstāj norādījumus konkrētā ierīces veidā."],"h2-steckanschluss":["Kas jāpārbauda pirms lādētāja pievienošanas?","Elektriskā paceļamā darba platforma ir jāuzlādē.","Izmantojiet jebkuru kontaktligzdu neatkarīgi no stāvokļa un drošinātāja.","Pārbaudiet piemērotu savienojumu un nebojātu kabeli saskaņā ar ražotāja norādījumiem.","Uzlādes laikā regulāri atvienojiet strāvas kontaktdakšu.","Piemēroti un neskarti elektriskie savienojumi pasargā no elektriskās strāvas trieciena un ugunsgrēka."],"h2-absperrpersonal":["Pacelšanas darbu laikā norobežotajā zonā iekļūst cilvēks. ko tu dari?","Jūs varat redzēt personu tieši zem darba groza.","Turpiniet braukt, ja persona valkā aizsargķiveri.","Nometiet instrumentu viņu virzienā kā brīdinājuma signālu.","Pārtrauciet bīstamo kustību un atbrīvojiet zonu.","Barjera neaizvieto bīstamās zonas novērošanu ekspluatācijas laikā."],"k2-arbeitsplanung":["Kas jāiekļauj darba sagatavošanā pirms celtņa darbības?","Krava, atrašanās vieta un transporta maršruts vēl nav saskaņoti.","Vispirms paceliet smagāko kravu bez turpmākas plānošanas.","Atzīmējiet tikai īsāko maršrutu zāles grīdā.","Iepriekš noskaidrojiet kravnesību, stropes, kravas ceļu un bīstamo zonu.","Plānotai celtņa kustībai ir nepieciešama piemērota kravas apstrāde, droši maršruti un saskaņoti aizsardzības pasākumi."],"k2-hakenposition":["Kā celtņa āķis ir novietots virs kravas pirms pacelšanas?","Piestiprināšanas punkti atrodas zem celtņa.","Pēc iespējas vertikāli virs smaguma centra atbilstoši pieturai.","Nobīdiet tālu uz sāniem, lai krava ātrāk iešūpotos.","Jebkurā gadījumā pie kravas ārējās malas, neatkarīgi no smaguma centra.","Spēka vertikāla pielietošana un piemēroti enkura punkti samazina sānu kustību un nekontrolētas kustības."],"k2-hakengabel":["Slodzes āķis parāda ievērojamu deformāciju. Kas attiecas?","Šķiet, ka āķis ir saliekts no ierastā stāvokļa.","Ar nākamo slodzi salieciet deformāciju atpakaļ.","Apturiet celtņa darbību un ļaujiet ekspertam pārbaudīt āķi.","Pievienojiet tikai vieglas kravas un turpiniet strādāt.","Deformācija var ietekmēt āķa drošību; neatļauta turpmāka izmantošana nav atļauta."],"k2-zugueberlast":["Slogs ir smagāks, nekā sākotnēji pieņemts. ko tu dari?","Gatavošanās laikā parādās jauna informācija par svaru.","Aizstāt drošības rezervi ar ātrāku pacelšanu.","Ignorējiet kravas svaru, pievienojot to citam punktam.","Nosakiet faktisko slodzi un atkārtoti pārbaudiet slodzes ierobežojumus.","Drošai celšanai nepieciešami uzticami kravas dati un atbilstība visām attiecīgajām kravnesībām."],"k2-arbeitskorb":["Vai parasts celtņa āķis var viegli pārvadāt cilvēkus?","Cilvēks vēlas nokļūt augstā darba vietā.","Nē, pasažieru pārvadājumiem ir nepieciešamas atļautas īpašas iespējas un pasākumi.","Jā, ja cilvēks turas pie stropes virves.","Jā, tiklīdz insults tiek veikts īpaši lēni.","Cilvēku pārvadāšana ir atļauta tikai ar īpašiem šim nolūkam paredzētiem nosacījumiem."],"k2-bruecke":["Tilta celtnis pārvietojas pa koplietošanas zāles celiņu. Kas ir svarīgi?","Darbinieki paliek zem transporta maršruta.","Brauciet ar kravu tieši virs darbinieku galvām.","Efektīvi uzturiet kravas maršrutu un satiksmes zonu skaidru un drošu.","Izmantojiet tikai brīdinājuma signālu, nevis turpmākos pasākumus.","Riska grupā esošie cilvēki nedrīkst atrasties zem piekārtām kravām vai savā transportēšanas ceļā."],"k2-zweitekrane":["Divi celtņi strādā vienā zonā. Kas ir nepieciešams?","Izlices vai kravas var sadurties viena ar otru.","Abi celtņu operatori strādā vienlaikus bez iepriekšējas vienošanās.","Kustības tiek apzināti paātrinātas, lai izvairītos no krustojumiem.","Koordinēt darbības un veikt atbilstošus pasākumus, lai novērstu savstarpējus draudus.","Darba jomām, kas pārklājas, ir nepieciešama koordinēta darbības organizācija un piemēroti drošības pasākumi."],"k2-pruefbuch":["Kāda ir obligātās atkārtotās celtņa apskates nozīme?","Mašīna tiek regulāri izmantota ekspluatācijā.","Tas papildina operatīvo kontroli ar noteikto ekspertīzi.","Tas neatgriezeniski aizstāj jebkuru vizuālo pārbaudi pirms darba sākšanas.","Tas ir nepieciešams tikai pēc avārijas.","Periodiskajām pārbaudēm un pastāvīgajām darbības kontrolēm ir dažādi uzdevumi."],"k2-absetzflaeche":["Paredzētais novietošanas laukums ir nevienmērīgs. Kā tu rīkojies?","Novietojot kravu, tā var apgāzties.","Novietojiet slodzi uz viena stūra un ļaujiet tai karāties nemainītā veidā.","Sagatavot piemērotas, nesošas un stabilas pamatnes vai virsmas.","Nolaižot zem kravas, novietojiet vienu cilvēku.","Novietošanas vietām ir droši jāatbalsta krava un jānovērš bīstamas apgāšanās vai ripošanas kustības."],"k2-anfahrbereich":["Pirms celtnis sāk kustēties, braukšanas zonā atrodas viens cilvēks. ko tu dari?","Maršrutu bloķējis cilvēks.","Pabīdiet personu malā ar īsu testa braucienu.","Pārvietojieties, izmantojot tikai gala slēdzi bez vizuālas pārbaudes.","Sāciet kustību tikai tad, kad bīstamā zona ir brīva un droša.","Braukšanas un pagrieziena kustības nedrīkst apdraudēt cilvēkus."],"k2-schlaffseil":["Kāpēc pacēlāja trose nedrīkst nekontrolējami atslābt, kad tā ir nolaista?","Krava ir, āķis ir nolaists tālāk.","Lai virve un āķi neiesprūstu vai netiktu pakļauti nekontrolētai slodzei.","Lai pēc tam kravu varētu vilkt uz sāniem aiz virves.","Lai stropes pašas atdalītos no āķa.","Nekontrolēta kabeļa izvilkšana var izraisīt sapīšanu un bīstamas kravas kustības."],"k2-pendel":["Transportējamā krava sāk šūpoties. Kas ir pareizi?","Krava pārvietojas uz sāniem vairāk nekā plānots.","Kompensējiet ar ātrām pret kustībām un pilnu ātrumu.","Kontrolēti samaziniet kustības un nomieriniet pārvietošanos bez cilvēkiem bīstamajā zonā.","Turiet šūpojošo slodzi ar kailām rokām.","Svārstīgās slodzes var ietekmēt cilvēkus un telpas; mierīgas kustības samazina risku."],"k2-funkakku":["Celtņa radiovadībai ir vājš akumulators. Kas attiecas?","Pacelšanas laikā savienojums var pārtrūkt.","Ātri paceliet kravu, pirms vadības ierīce nedarbojas.","Ja savienojums tiek zaudēts, pārvietojiet kravu, velkot aiz stropes.","Pirms lietošanas nodrošiniet uzticamu vadības savienojumu.","Uzticama vadība un komunikācija ir priekšnoteikumi kontrolētām celtņa kustībām."],"k2-mehrereanschlaeger":["Divi cilvēki vienlaikus dod dažādus signālus celtņa vadītājam. Kas ir pareizi?","Zīmes ir pretrunā viena otrai.","Pārtrauciet kustību un noskaidrojiet skaidru atbildību.","Dodiet priekšroku tālāk esošās personas zīmei.","Turpiniet kustību atbilstoši savām izjūtām.","Celtņu vadītājiem ir nepieciešama skaidra un nepārprotama komunikācija, it īpaši, ja kravas maršruti ir neskaidri."],"k2-endabschaltung":["Kāpēc gan nedrīkst ļaunprātīgi izmantot gala slēdzi kā parastu gājiena ierobežojumu?","Krava bieži tiek pārvietota līdz maksimālajam pacelšanas attālumam.","Ierobežošanas slēdži parasti nodrošina ātrāku pacelšanu bez redzamības.","Gala slēdži ir drošības ierīces un neaizstāj kontrolētu darbību.","Ar katru sitienu tiem jābūt pēc iespējas spēcīgākiem.","Drošības ierīces kalpo aizsardzībai pret briesmām, un tās nedrīkst pārmērīgi izmantot, kā plānots."],"k2-wetterbeobachtung":["Vējš ievērojami palielinās pie lielas teritorijas slodzes. Kas ir nepieciešams?","Liels komponentu laukums darbojas kā bura.","Vienmēr paceliet kravu augstāk, lai vējam būtu mazāka ietekme.","Nomainiet stropes pret plānākām.","Novērtējiet vēja un darbības ierobežojumus un, ja nepieciešams, noregulējiet pacelšanu.","Vējš var radīt ievērojamus papildu spēkus un svārsta kustības, īpaši ar lielas platības slodzēm."],"k2-ortswechsel":["Kas ir svarīgi, pārvietojot autoceltni uz jaunu vietu?","Mainās grunts un atbalsta apstākļi.","Pirms kravas atkārtotas pacelšanas pārbaudiet statīva atrašanās vietu un atbalstu.","Lietojiet iestatījumus no iepriekšējās atrašanās vietas bez pārbaudes.","Pacelšanas laikā noregulējiet balstu.","Katrai uzstādīšanas vietai var būt atšķirīgi zemes un atbalsta slodzes apstākļi."],"k2-betriebsbereich":["Ir paredzēts, ka celtnim jāstrādā pāri ielai. Kas ir jāprecizē?","Trešās personas var nokļūt bīstamajā zonā.","Nodrošiniet ceļu tikai ar brīdinājuma signālu.","Nepieciešamās bloķēšanas, balsošanas un aizsardzības pasākumi centrmezgla priekšā.","Paceliet kravu virs transportlīdzekļiem pēc iespējas ātrāk, nenostiprinot to.","Droša satiksmes maršrutēšana novērš nevajadzīgu risku trešajām personām no kravas un celtņa kustībām."],"k2-hochheben":["Pēc testa pacelšanas krava karājas skaidri greizi. Kas ir pareizi?","Acīmredzot fokuss tika nepareizi novērtēts.","Turpiniet celšanu, lai nelīdzsvarotība izlabotos pati par sevi.","Lieciet vienam cilvēkam vilkt nosvērto slodzi.","Droši novietojiet kravu un vēlreiz pārbaudiet stiprinājumu un smaguma centru.","Testa pacēlājs tiek izmantots, lai pirms transportēšanas noteiktu nepareizu stiprinājumu un nestabilas kravas pozīcijas."],"k2-schwebelast":["Vai paceltu kravu var atstāt karājoties bez uzraudzības?","Maiņa beidzas, bet slodze joprojām ir uz āķa.","Nē, droši nolaidiet kravu un pareizi nostipriniet celtni.","Jā, ja celtnis ir nobloķēts, lai tas nenokļūtu.","Jā, ja vien uz zemes ir brīdinājuma zīme.","Principā piekārtās kravas nedrīkst atstāt bez uzraudzības."],"k2-mitnahme":["Kolēģe vēlas braukt ar celtņa kravu. Kas attiecas?","Krava jātransportē uz augstāku punktu.","Jāšana ir atļauta, ja kolēģis valkā ķiveri.","Cilvēkus nedrīkst pārvadāt uz parastajām kravām vai piestiprināt pie tām.","Brauciens vienmēr ir atļauts, ja vien kolēģis celtņa vadītājs pazīst.","Cilvēku pārvadāšana kopā ar kravām rada ievērojamu krišanas un saspiešanas risku."],"k2-warnsignal":["Celtņa darbības brīdinājuma sistēma nedarbojas. Kas ir pareizi?","Brīdinājums pirms izbraukšanas vairs nav iespējams.","Ignorējiet sistēmu, kad dzinējs darbojas.","Neatgriezeniski nomainiet brīdinājumu, pieskaroties korpusam.","Ziņojiet par kļūdu, kas saistīta ar drošību, un pārtrauciet darbību saskaņā ar instrukcijām.","Nepieciešamajām brīdinājuma ierīcēm jābūt funkcionālām, lai cilvēki tiktu laikus aizsargāti."],"k2-schneekante":["Mobilais celtnis ir jāatbalsta uz sasalušas nelīdzenas zemes. Kas attiecas?","Atkausējot augsne var zaudēt savu nestspēju.","Novērtējiet kravnesību un atbalsta situāciju faktiskajos apstākļos.","Sasalušai zemei ​​vienmēr ir kāda nestspēja.","Novietojiet balstus tikai uz maziem akmeņiem.","Temperatūra, mitrums un zemes dzīļu struktūra ietekmē celtņu vietu nestspēju."],"k2-laufkatze":["Ratiņi virzās uz šķērsli. Kā tu rīkojies?","Braukšanas zonā atrodas objekts.","Lēnām bīdiet priekšmetu kopā ar kravu.","Savlaicīgi pārtrauciet kustību un droši noņemiet šķērsli.","Brauciet garām šķērslim ar palielinātu ātrumu.","Celtņa kustības jāvada tā, lai nenotiktu sadursmes ar šķēršļiem."],"k2-anschlagaufnahme":["Jums vajadzētu uzņemt kravu, izmantojot neparedzētu cilpu. Kas ir pareizi?","Cilpa varētu būt paredzēta tikai pārsega montāžai.","Katra cilpa ir piemērota pilnai celtņa slodzei.","Ielādējiet cilpā tikai divus cilvēkus vienlaikus.","Pirms lietošanas pārbaudiet stiprinājuma punkta kravnesību un piemērotību.","Ne katra esošā cilpa ir stabils stiprinājuma punkts celtņa kravām."],"l2-seilbruch":["Stiepļu trosē ir redzami vairāki pārrautu atsevišķi vadi. Kas ir pareizi?","Pārrāvuma vietas atrodas nesošās virves zonā.","Neturpiniet lietot pacēlāju un lūdziet to profesionāli novērtēt.","Salieciet stieples galus atpakaļ ar kailām rokām.","Turpiniet izmantot virvi, ja slodze ir īpaši viegla.","Vadu pārrāvumi var būt izmešanas kritērijs; Bojātās virves ir profesionāli jānovērtē."],"l2-schaekel":["Kas ir svarīgi, lietojot važus?","Stropu un kravu savieno važas.","Nomainiet skrūvi ar jebkuru naglu.","Pārbaudiet piemērotu kravnesību, nebojātu stāvokli un pareizās skrūves.","Novērtējiet kravnesību, pamatojoties uz krāsu.","Važām jābūt atbilstoša izmēra, jāizmanto pilnībā un paredzētajā iekraušanas virzienā."],"l2-tragfaehigkeit":["Kas jāņem vērā, izmantojot vairākus pavedienus?","Virzieni virzās leņķī pret vertikāli.","Vienkārši pievienojiet katras daļas kravnesību pēc vēlēšanās.","Pakariet slodzi tikai uz vieglākās šķipsnas.","Ņem vērā visa veida enkura un leņķa nestspēju.","Slīpuma leņķis un efektīvais dzīslu skaits būtiski ietekmē pieļaujamo slodzi."],"l2-schweissnaht":["Vai improvizētu enkura punktu var piemetināt pie slodzes?","Nav piemērotu kravas savākšanas punktu.","Izmantojiet tikai pareizi izstrādātus un apstiprinātus enkura punktus.","Pietiek ar jebkuru metināšanas šuvi bez pārbaudes.","Ievietojiet āķi caur atveri metāla loksnē.","Ir jāpierāda, ka stiprinājuma punkti ir piemēroti celšanas spēkiem."],"l2-einseitig":["No vienas puses slodze ir ievērojami lielāka. Kā jūs to darāt?","Smaguma centrs atrodas ārpus ģeometriskā centra.","Atstājiet visas šķipsnas vienāda garuma neatkarīgi no smaguma centra.","Nosakiet smaguma centru un attiecīgi noregulējiet pozīciju.","Vispirms paceliet kravu līdz pilnam pacelšanas augstumam.","Ja smaguma centrs atrodas ārpus centra, kravas var negaidīti apgāzties vai atsevišķas šķipsnas var tikt pārslogotas."],"l2-kettenriss":["Kas attiecas uz ķēdes stropēm ar redzamām plaisām?","Vienā no ķēdes posmiem ir plaisa.","Atzīmējiet plaisu ar krāsu un paceliet to nemainītā veidā.","Aptiniet saiti ar stiepli un izmantojiet to atkārtoti.","Nekavējoties noņemiet ķēdi un informējiet atbildīgo personu.","Plaisas nesošajos ķēžu posmos ir ar drošību nozīmīgi bojājumi, un to darbība ir jāpārtrauc."],"l2-lastfuehrung":["Kā pārvadāt lielu kravu, ja pastāv rotācijas risks?","Pacelšanas laikā krava var šūpoties uz sāniem.","Izmantojiet atbilstošas ​​vadības ierīces un drošu attālumu.","Braukšanas laikā turiet kravu tieši starp rokām.","Pakāpieties zem slodzes un izlīdziniet to no apakšas.","Kravas vadība nedrīkst izraisīt roku vai ķermeņa nokļūšanu bīstamajā zonā."],"l2-schnueren":["Kas ir svarīgi, piestiprinot mežģīnes?","Strope tiek virzīta ap kādu sastāvdaļu.","Pieņemsim tādu pašu kravnesību kā jebkura cita veida enkuram.","Ievērojiet stiprinājuma veida piemērotību un pieļaujamo slodzi atbilstoši marķējumam.","Nepārbaudot jebkādā mērā savelciet stropes zobratu kopā.","Šņorēšanas stiprinājuma veids var mainīt pieļaujamo kravnesību, un tas ir jāizmanto pareizi."],"l2-winkelmesser":["Kāpēc jūs nevarat ignorēt plakanu dzīslu leņķi?","Divas stropu līnijas stiepjas gandrīz horizontāli pret kravu.","Plakans leņķis automātiski padara dzīslu stiprāku.","Slodze vienmēr tiek sadalīta vienādi neatkarīgi no leņķa.","Lieli stieņu spēki var pārsniegt pieļaujamo kravnesību.","Palielinoties leņķim pret vertikāli, palielinās spriegumi uz dzīslām."],"l2-heisse-last":["Kas jums jāpārbauda, ​​​​vai ir karsta slodze?","Tērauda daļa nesen tika termiski apstrādāta.","Ievērojiet stropu temperatūras ierobežojumus un piemērotu izvēli.","Katra tekstila strope var izturēt jebkuru temperatūru.","Marķējumam nav nozīmes, kad tas ir karsts.","Temperatūra var ietekmēt stropu pieļaujamo kravnesību."],"l2-abstand":["Vai, noliekot to, varat likt pirkstus zem slodzes?","Kravai jānolaižas uz virsmas ar milimetru precizitāti.","Jā, ja valkā darba cimdus.","Nē, ievērojiet distanci un izmantojiet atbilstošus palīglīdzekļus.","Jā, ja celtņa kustība ir īpaši lēna.","Ķermeņa daļas starp slodzi un pamatni var iesprūst."],"l2-verbindung":["Stropes ķēdes savienojošais posms nav bloķēts. Kas attiecas?","Trūkst stiprinājuma.","Izmantojiet aizbīdni bez slēdzenes, kad neviens to neskatās.","Aizzīmogojiet elementu ar līmlenti.","Nesitiet, kamēr stiprinājums nav pareizi nostiprināts.","Savienojošie elementi ir jānostiprina pilnībā un atbilstoši to konstrukcijai."],"l2-lasthaken":["Ko jūs pārbaudāt, karājoties uz celtņa āķa?","Āķī jāievada vairākas stropes.","Nodrošiniet āķu un balstiekārtas drošu piegulšanu un piemērotību.","Novietojiet stropes uz āķa gala.","Nomainiet āķa slēdzeni ar kabeļu saiti.","Spēks jāpiemēro paredzētajās vietās paredzētajās vietās."],"l2-fasern":["Pacelšanas siksna liecina par nopietnu raupjumu un šķiedru bojājumu. Kas ir pareizi?","Atbalsta šķiedras ir redzami bojātas.","Pārklājiet bojājumus ar citu mezglu.","Atdaliet pacelšanas siksnu un lūdziet to pārbaudīt speciālistam.","Pēc tam paceliet kravu ātrāk.","Bojātas nesošās šķiedras var ievērojami samazināt celšanas siksnas nestspēju."],"l2-anheben":["Kas attiecas uz uzreiz pēc pirmā pacelšanas centimetra?","Krava tikai paceļas no pamatnes.","Bez kontroles pavelciet kravu pilnā augstumā.","Zem slodzes pārbaudiet, vai stropes ir nospriegotas.","Pārbaudiet pieturas pozīciju, līdzsvaru un kustības uzvedību.","Kontrolēts testa pacēlājs padara iespējamo nestabilitāti redzamu pirms tālākas transportēšanas."],"l2-lastgewichte":["Kravas svars nav zināms. Kas ir pareizi?","Komponentam nav svara marķējuma.","Pirms stropu izvēles nosakiet noslogojamo svaru.","Novērtējiet svaru, pamatojoties uz kravas krāsu.","Izmantojiet jebkuru dubultā garuma stropi.","Bez zināma vai droši noteikta svara stropu piemērotību nevar droši pārbaudīt."],"l2-lose-teile":["Uz paceļamās kravas ir vaļīgi instrumenti. ko tu dari?","Pacelšanas laikā instrumenti var nokrist.","Braukšanas laikā turiet instrumentus ar vienu roku.","Pirms pacelšanas noņemiet vai efektīvi nostipriniet vaļīgos priekšmetus.","Paceliet kravu nedaudz ātrāk, lai nekas neslīdētu.","Irdeni priekšmeti var nokrist un apdraudēt apkārtnē esošos cilvēkus."],"l2-wind":["Spēcīgā vējā tiek piestiprināta liela slodze. Kas attiecas?","Komponents piedāvā vējam lielu uzbrukuma virsmu.","Paceliet slodzi, neņemot vērā šūpošanās kustības.","Papildu cilvēkiem vajadzētu tieši turēt slodzi.","Novērtējiet vēja apstākļus un atturieties no celšanas, ja situācija nav droša.","Vēja spēki var ietekmēt kravas vadību un stabilitāti transportēšanas laikā."],"l2-unterlage":["Kāpēc atšķiršanas laikā ir svarīgi piemēroti dokumenti?","Apaļa krava ripotu prom pa zemi.","Novietojiet kravu stingri uz leju un, ja nepieciešams, nostipriniet to pret ripošanu.","Atstājiet kravu stāvēt tieši uz stropēm.","Pastumiet dokumentus zem kravas tikai pēc to nolikšanas.","Piemēroti balsti novērš apgāšanos un nevēlamas kustības nolaižoties."],"l2-transportweg":["Kas jāsaskaņo pirms kravas transportēšanas?","Krava tiek pārvietota pa vairākām darba zonām.","Tikai paredzamais centrmezgla darbības ilgums.","Drošs kravas ceļš, komunikācija un nepieciešamās barjeras.","Vienam cilvēkam vajadzētu parādīt ceļu zem kravas.","Kravu pārvadāšanai nepieciešami droši satiksmes ceļi un skaidra koordinācija."],"l2-schutzschlauch":["Kam jāpievērš uzmanība, lietojot stropes ar aizsargšļūteni?","Josla atrodas pret nelīdzenu malu.","Jebkura plāna auduma drāna aizstāj piemērotu malu aizsardzību.","Aizsargšļūtene novērš jebkuru pieļaujamo slodzes ierobežojumu.","Izvēlieties aizsarglīdzekļus atbilstoši piemērotības un lietošanas prasībām.","Aizsarglīdzekļiem jāatbilst materiālam, malai un paredzētajai slodzei."],"l2-reinigung":["Pacelšanas siksna bija piesārņota ar nezināmu ķīmisku vielu. Kas ir pareizi?","Lentu vairs nevar skaidri novērtēt.","Pārtrauciet lietošanu un profesionāli noskaidrojiet saderību vai stāvokli.","Notīriet ar jebkuru šķīdinātāju un nekavējoties turpiniet celšanu.","Ignorējiet ķīmisko vielu, kamēr lente ir sausa.","Ķimikālijas var ietekmēt tekstila stropu izturību."],"l2-aufhaengung":["Ko jūs pārbaudāt, vai balstiekārtas saitē nav vairākas dzīslas?","Divas šķipsnas ir novietotas kopā suspensijā.","Āķa galā var pārvietoties pēc vēlēšanās.","Visiem savienojošajiem elementiem jābūt piemērotiem un sakārtotiem, kā paredzēts.","Mazām slodzēm var izmantot gredzenu ar plaisu.","Apturēšanas un savienojuma elementiem jābūt nesošiem un pareizi sakārtotiem."],"l2-einweiserrolle":["Ko piemēro, ja uzbrucējam un celtņa operatoram nav redzamības līnijas?","Nesējs bloķē nolaišanas punkta skatu.","Saskaņojiet, zvanot vairākiem cilvēkiem bez atbildības.","Pārvietojiet slodzi, pamatojoties uz troksni, bez norādījumiem.","Organizējiet skaidru, drošu saziņu un pārtrauciet to, ja tā ir neskaidra.","Redzamības trūkums ir jākompensē ar efektīvu koordināciju un drošu komunikāciju."],"l2-ausserbetrieb":["Bojāta strope tika sakārtota. Kas vēl ir svarīgi?","Tā joprojām ir brīvi pieejama kopā ar lietošanai gataviem resursiem.","Nodrošiniet pret turpmāku nejaušu lietošanu un informējiet atbildīgo personu.","Atgrieziet preci bez marķējuma uz inventāru.","Izmantojiet to atkārtoti tikai tad, ja pārvadājat īpaši vieglu kravu.","Izlietotās stropes pirms turpmākas lietošanas ir droši jāaizsargā."],"b2-schwenkradius":["Kāpēc ekskavatora aizmugures šūpošanās rādiuss ir kritisks?","Aste pārvietojas pa ierobežotu darba zonu.","Trešās personas var noķert ar šūpojošo virsbūvi.","Šūpošanās rādiuss neietekmē cilvēkus, kas atrodas blakus mašīnai.","Aizmugure vienmēr pārvietojas tikai braukšanas virzienā.","Pagriežot, bīstamā zona rodas arī aiz mašīnas."],"b2-verkehrseinweiser":["Kā tiek nodrošināta braukšanas kustība, ja redzamība ir apgrūtināta?","Ekskavatoram ir jāmanevrē aiz šķēršļa.","Brauciet, neredzot signalizētāja signālus.","Ja nepieciešams, organizējiet atbilstošu instruktāžu ar skaidru saziņu.","Nodrošiniet atpakaļgaitu, tikai vienu reizi nosaucot signālu.","Mulsinoši maršruti prasa efektīvus pasākumus, lai novērstu sadursmes un iesprūšanu."],"b2-standplatz":["Kas attiecas uz ekskavatora stendu uz nogāzes?","Grīda ir slīpa un var būt slidena.","Mašīna var izstiepties tik tālu, cik vien vēlas jebkurā slīpumā.","Vienmēr uzstādiet ekskavatoru uz irdenas zemes slāņa.","Pirms lietošanas pārbaudiet iekārtas stabilitāti un darbības ierobežojumus.","Slīpuma slīpums un apakškārta būtiski ietekmē stabilitāti."],"b2-oberleitung":["Kāpēc jāplāno strēles attālums no elektrolīnijām?","Pagriežot strēli, izlice var pietuvoties kabelim.","Elektriskā pārslēgšanās iespējama arī bez tieša kontakta.","Elektrību var vadīt tikai spainis, nevis strēles.","Ar sausu augsni katrs attālums ir automātiski drošs.","Pirms tuvošanās elektriskajām sistēmām ir jānoskaidro lietošanas ierobežojumi un aizsargattālumi."],"b2-fremdperson":["Garāmgājējs ieiet būvlaukumā panoramēšanas zonā. Kas ir pareizi?","Cilvēks pēkšņi stāv pie ekskavatora kausa.","Paceliet lāpstu uz augšu un pagrieziet to virs personas.","Nekavējoties pārtrauciet kustību un notīriet zonu.","Vienkārši turpiniet vērot cilvēku no sānu loga.","Cilvēkus bīstamajā zonā nedrīkst apdraudēt darba kustības."],"b2-parkstellung":["Kā tiek nodrošināta zemes pārvietošanas mašīna pēc darba pabeigšanas?","Ekskavators būvlaukumā paliek bez uzraudzības.","Atstājiet karoti galvas līmenī.","Ļaujiet dzinējam darboties bez uzraudzības.","Nolieciet darba aprīkojumu, nostipriniet mašīnu un nepieļaujiet neatļautu lietošanu.","Pareiza autostāvvieta samazina nejaušu kustību un nesankcionētu piekļuvi."],"b2-eigenlast":["Kāpēc, ceļot ar ekskavatoru, aprīkojuma ierobežojumi ir ļoti svarīgi?","Uz izlices ir jāuzņem smaga slodze.","Pretējā gadījumā var tikt pārsniegta stabilitāte un pieļaujamā kravnesība.","Jebkura mašīna var pacelt jebkuru kravu, ja vien kauss ir piemērots.","Tikai stropes virves garums nosaka risku.","Informācija par celtspēju un kravnesību ir atkarīga no aprīkojuma un pielietojuma situācijas."],"b2-untergrundhohlraum":["Grīda virs vecā pagraba varētu būt doba. ko tu dari?","Jums jāiebrauc ar ekskavatoru šajā zonā.","Šķērsojiet vietu ar maksimālu impulsu.","Pirms braukšanas tālāk noskaidrojiet kravnesību un iespējamos dobumus.","Vienkārši uzlieciet lielu slodzi uz virsmas.","Dobumi var sabrukt zem mašīnas svara un izraisīt mašīnas avāriju."],"b2-feuchtigkeit":["Pēc stipra lietus uzbērums kļūst mīksts. Kas ir pareizi?","Netālu no uzbēruma malas strādā ekskavators.","Pārvietojiet mašīnu tuvāk malai, lai palielinātu sasniedzamību.","Ignorējiet izmaiņas līdz maiņas beigām.","Atkārtoti novērtējiet augsnes un stabilitātes apstākļus.","Mitruma iekļūšana var mainīt uzbērumu nestspēju un stabilitāti."],"b2-bodenprobe":["Kāpēc pirms rakšanas ir jāpārbauda cauruļvadu plāni?","Zem plānotās rakšanas varētu palaist kabeļi.","Lai varētu identificēt līnijas un plānot piemērotus drošības pasākumus.","Lai rakšanas darbus varētu veikt ātrāk, neatkarīgi no trešo pušu sistēmām.","Tā kā mašīnas nekad nedrīkst izmantot kabeļu tuvumā.","Pazemes padeves līnijām pirms rakšanas darbiem ir nepieciešams uzticams atrašanās vietas noskaidrojums."],"b2-maschinenzugang":["Kas attiecas uz iekāpšanu zemes pārvietošanas mašīnā un izkāpjot no tās?","Mašīna atrodas uz nelīdzena reljefa.","Izbīdiet hidraulisko līniju no kabīnes.","Izmantojiet norādītos pakāpienus un nodrošiniet drošu pamatu.","Mašīnas darbības laikā uzleciet uz grozāmās sviras.","Droši kāpumi un piemēroti apstāšanās punkti samazina kritiena un saspiešanas risku."],"b2-kupplung":["Kā pārbaudīt jaunu ekskavatoru pēc uzstādīšanas?","Kauss ir savienots ar ātro savienotāju.","Tikai vizuāli vērtējiet karoti no lielāka attāluma.","Pakāpieties tieši zem paceltās karotes.","Nodrošiniet pareizu bloķēšanu un noteiktās kontroles darbības.","Nepareizi bloķēti stiprinājumi var atslēgties un apdraudēt cilvēkus."],"b2-hydraulikwartung":["Kāpēc hidrauliskās līnijas nedrīkst atvērt zem spiediena?","Ir jānomaina šļūtene.","Izplūstošais šķidrums var izraisīt nopietnas traumas augsta spiediena dēļ.","Spiediens vienmēr neļauj eļļai izplūst.","Atvērtu līniju var droši pārbaudīt ar rokām.","Augstspiediena šķidrums var iekļūt audos, un tam ir nepieciešama droša spiediena samazināšana."],"b2-fahrweg":["Jābrauc pāri pagaidu būvniecības tiltam. Ko jūs pārbaudāt?","Tilts ir paredzēts tikai noteiktām slodzēm.","Vai tilta krāsa atbilst mašīnai.","Kravnesība un atbilstība mašīnas svaram un izmēriem.","Tikai vai pa tiltu jau ir uzbraukusi vieglā mašīna.","Pagaidu konstrukcijas drīkst izmantot tikai to nestspējas robežās."],"b2-baggertransport":["Kas ir svarīgi, transportējot ekskavatoru ar zemu iekrāvēju?","Mašīna tiek nogādāta nākamajā būvlaukumā.","Ļaujiet darba aprīkojumam brīvi izvirzīties pāri malai.","Braukšanas laikā turiet atvērtas kabīnes durvis.","Nostipriniet mašīnu atbilstoši transportēšanas specifikācijām un pārbaudiet iekraušanas aprīkojumu.","Transportēšanas slēdzenes un piemērotas iekraušanas iekārtas novērš slīdēšanu un krišanu."],"b2-schaufelfuellung":["Kāpēc frontālais iekrāvējs nedrīkst braukt ātri ar augstu paceltu kausu?","Slodze ir smaga un zeme ir nelīdzena.","Augsts smaguma centrs var palielināt apgāšanās risku un redzamības problēmas.","Kauss automātiski stabilizējas lielā ātrumā.","Lāpstas augstumam nav nozīmes stabilitātei.","Paaugstināts smaguma centrs parasti pasliktina stabilitāti braukšanas un līkumos."],"b2-fussgaenger":["Kā tu uzvedies, manevrējot blakus gājējiem?","Piekļuve būvlaukumam ir arī gājēju celiņš.","Izmantojiet lāpstu, lai novirzītu gājējus uz sāniem.","Braukšanas kustību veiciet tikai tad, kad vieta ir droši brīva un pārvaldāma.","Vienkārši nosauciet vienu reizi un brauciet lēnām bez redzamības.","Transportlīdzekļu un pasažieru satiksme ir efektīvi jānodala vai droši jāsaskaņo."],"b2-ueberlastwarnung":["Paceļot, iekārta ziņo par pārslodzi. ko tu dari?","Pacelta krava sasniedz pieļaujamās robežas.","Izslēdziet brīdinājumu un turpiniet to pacelt bez izmaiņām.","Mašīnas darbības laikā pēkšņi pievelciet slodzi.","Apturiet bīstamas kustības un droši labojiet slodzes situāciju.","Pārslodzes brīdinājumi norāda uz iespējamiem ierobežojumu pārkāpumiem un stabilitātes riskiem."],"b2-wasserleitung":["Veicot rakšanas darbus, tiek atsegta nezināma caurule. Kas attiecas?","Līnija būvniecības plānos nav uzrādīta.","Pārtrauciet darbu skartajā zonā un profesionāli identificējiet līniju.","Mēģiniet pārvietot auklu ar ekskavatoru lāpstu.","Turpiniet rakšanu tieši zem līnijas, nepārbaudot.","Nezināmas līnijas var izraisīt elektrības, gāzes vai ūdens apdraudējumu."],"b2-hangefahrt":["Kā vadīt ekskavatoru stāvā nogāzē?","Plānotais maršruts ved pa nogāzi.","Brauciet pāri nogāzei neatkarīgi no ražotāja ierobežojumiem.","Ievērojiet mašīnas pieļaujamo slīpumu un noteikto braukšanas stilu.","Pagrieziet izlici tālu uz āru, lai līdzsvarotu transportlīdzekli.","Pieļaujamais slīpums ir atkarīgs no mašīnas, virsmas un ražotāja informācijas."],"b2-schlechtebeleuchtung":["Strādājot tumšā bedrē, redzamība ir nepietiekama. Kas ir pareizi?","Jūs gandrīz neredzat cilvēkus un šķēršļus.","Palieliniet rakšanas ātrumu, lai ātri pabeigtu darbību.","Neizmantojiet gaismas, kamēr darbojas dzinējs.","Pārtrauciet darbu, līdz bīstamās zonas ir pietiekami redzamas.","Lai kontrolētu mašīnas kustību, ir nepieciešama droša braukšanas un darba zonu redzamība."],"b2-kettenverschleiss":["Ikdienas pārbaudē tiek pamanīta bojāta kāpurķēde. ko tu dari?","Ķēdes savienojums parāda skaidrus bojājumus.","Neturpiniet lietot mašīnu nekontrolēti un ziņojiet par bojājumiem.","Turpiniet braukt ar lielu ātrumu, lai ķēde iztaisnotos.","Turpiniet strādāt tikai uz mīkstas zemes bez pārbaudes.","Piedziņas bojājumi var pasliktināt vadāmību un stabilitāti."],"b2-ladearbeiten":["Jūs iekraujat kravas automašīnu ar ekskavatoru. Kas ir svarīgi?","Kravas automašīnas vadītājs paliek tuvu iekraušanas zonai.","Pagrieziet kausu virs neaizsargātās vadītāja kabīnes.","Neļaujiet cilvēkiem palikt bīstamajā zonā un koordinējiet procesus.","Sāciet ielādi, nesazinoties ar vadītāju.","Iekraušanas laikā pastāv materiāla krišanas un šūpošanās risks."],"b2-arbeitsunterbrechung":["Jūs pārtraucat rakšanas darbus sapulcei. Kas attiecas?","Mašīnai vajadzētu stāvēt vairākas minūtes, to nedarbinot.","Atstājiet pacelto lāpstu kā marķieri.","Atstājiet mašīnu bez uzraudzības ar ieslēgtu vilces piedziņu.","Droši novietojiet agregātu un nodrošiniet to pret nejaušu izmantošanu.","Pat īsiem pārtraukumiem ir nepieciešams drošs mašīnas stāvoklis."],"b2-rollmaterial":["Irdens materiāls var nokrist, transportējot ar riteņu iekrāvēju. Kas ir pareizi?","Iekrāvējs brauc tuvu darbiniekiem.","Droši paņemiet kravu un izvēlieties drošu braukšanas stilu ar piemērotu lāpstas pozīciju.","Paceliet lāpstu pēc iespējas augstāk, lai apkārtnei būtu skaidrs skats.","Paņemiet kravu, neierobežojot kausa pildījumu.","Brīvas kravas, augstas kausa pozīcijas un slikta redzamība var apdraudēt cilvēkus un satiksmi."]};
